             #241a13; /* reuses --container (idle/neutral tone) (ref:--container) */\n  --symbolFill--running:                #8cc08e; /* reuses --success (ref:--success) */\n  --symbolFill--faulted:                #e08a7a; /* reuses --error (ref:--error) */\n  --symbolFill--stopped:                #ab9578; /* reuses --label--disabled (muted ink) (ref:--label--disabled) */\n  --symbolStroke--default:              #3d2c1e; /* reuses --containerBorder (ref:--containerBorder) */\n  --symbolStroke--running:              #709a72; /* --success darkened 20% for a visible outline against its own fill (ref:--success) */\n  --symbolStroke--faulted:              #b36e62; /* --error darkened 20% for a visible outline against its own fill (ref:--error) */\n  --symbolStroke--stopped:              #897760; /* --label--disabled darkened 20% for a visible outline against its own fill (ref:--label--disabled) */\n  --pipeStroke:                         #3d2c1e; /* reuses --border (ref:--border) */\n  --pipePrimaryFill:                    #ab9578; /* reuses --label--disabled (muted ink -- an inactive/unqualified pipe) (ref:--label--disabled) */\n  --pipeSecondaryFill:                  #241a13; /* reuses --containerNested (a differentiated neutral tone) (ref:--containerNested) */\n  --pipeSelectStroke:                   #c08a4a; /* reuses --callToAction (selection highlight) (ref:--callToAction) */\n  --tooltip-background-color:           #241a13; /* reuses --containerNested (a raised-above-card tone) (ref:--containerNested) */\n  --boxShadow--inset:                   none; /* --boxShadow1 turned into an inset shadow (or "none" unchanged, for packs with no shadow token) (ref:--boxShadow1) */\n  --arrow-color:                        #ece0cb; /* reuses --icon (ref:--icon) */\n  --indicator:                          #8cc08e; /* reuses --success -- drives the LED component\'s "on" diode fill AND the quality-overlay "pending" state (IA\'s own dark.css uses a bright green for both, same semantic fit) (ref:--success) */\n  --indicatorOff:                       #151d15; /* --indicator darkened 85% -- the LED component\'s "off" diode fill; IA\'s own indicatorOff is a near-black shade of indicator\'s own hue, same ratio applied here (ref:--indicator) */\n  --contextBackground:                  #241a13; /* reuses --containerNested -- the right-click context-menu background. IA hardcodes this to --black in BOTH its light and dark themes, which is a real contrast bug for a light pack: the context menu\'s own text uses --label (dark ink on a light theme), so a literal black background would be near-illegible. --containerNested keeps it in the theme\'s own surface family and pairs correctly with --label either way (ref:--containerNested) */\n  --defaultSliderFocusColor:            rgba(192,138,74,0.5); /* --callToAction at IA\'s own 0.5 alpha -- the slider handle\'s focus glow. Reaches the ALTERNATE slider selector that actually consumes this var via var(); the PRIMARY .ia_slider__handle:focus selector hardcodes its own colour instead (see README\'s hard-coded-colour audit) and needs a compensating rule in globals.css, not a var override, to pick this up (ref:--callToAction) */\n  --callToAction--activeAlt:            #291d15; /* reuses --callToActionHighlight -- IA\'s own activeAlt (#093952) and callToActionHighlight (#0C2938) are both dark, similarly-saturated accent washes used for different components\' pressed/focused feedback (a dropdown option\'s focus background, a split-container handle\'s active-drag background); close enough in IA\'s own values that one derivation covers both meaningfully (ref:--callToActionHighlight) */\n  --callToAction--activeAltInvis:       #cb9f6b; /* reuses --callToAction--hover -- IA\'s own activeAltInvis (#0A6291) sits roughly midway between callToAction and callToActionHighlight in lightness; --callToAction--hover is already a mid-tone lighter accent in this generator and is the closest existing derived value without inventin