# Display order -- matches out/themes.json / the table on the Installer
# view. THEMES itself is keyed for O(1) lookup and whitelisting; this is
# the order things get installed/listed in.
THEME_ORDER = [
    'glass-violet',
    'glass-green',
    'leather-dark',
    'leather-light',
    'finance-ledger',
    'newsprint-dark',
    'nord-dark',
    'nord-light',
    'industrial-dark',
    'industrial-light',
]


def _data_dir():
    # Resolved dynamically -- verified live on 8.3.8. Never hardcode an
    # install path; different gateways mount data/ in different places.
    return str(IgnitionGateway.get().getSystemManager().getDataDir())


def _themes_root():
    return os.path.join(
        _data_dir(), "config", "resources", "core",
        "com.inductiveautomation.perspective", "themes")


def _rescan():
    # Config scan -- picks up newly written theme directories. Themes are
    # gateway CONFIG resources, not project resources: this is the same
    # scan as Config -> Platform -> Overview -> "Scan File System", not the
    # Projects page one.
    # requestScan() is async (returns a CompletableFuture); BLOCK on it so the
    # status read that follows a click sees the registered themes, not a stale
    # in-flight state. 30s cap; a timeout just means status lags a moment.
    from_future = IgnitionGateway.get().getConfigurationManager().requestScan()
    try:
        from java.util.concurrent import TimeUnit
        from_future.get(30, TimeUnit.SECONDS)
    except (Exception, Throwable):
        pass  # scan still runs; only the wait failed


def _write_theme_files(name):
    theme = THEMES[name]
    theme_dir = os.path.join(_themes_root(), name)
    if not os.path.isdir(theme_dir):
        os.makedirs(theme_dir)
    for filename, content in theme["files"].items():
        path = os.path.join(theme_dir, filename)
        handle = open(path, "wb")
        try:
            handle.write(content.encode("utf-8"))
        finally:
            handle.close()


def install(name):
    """Write one theme's files and request a scan. Refuses any name not
    in the embedded THEMES set -- never touches an IA built-in theme."""
    if name not in THEMES:
        raise ValueError("Unknown theme id '%s' -- refusing to write" % name)
    _write_theme_files(name)
    _rescan()
    return True


def install_all():
    """Write every embedded theme's files, then ONE scan at the end (not
    one per theme -- a scan is not free and 9 of them in a row is no more
    correct than 1)."""
    for name in THEME_ORDER:
        _write_theme_files(name)
    _rescan()
    return list(THEME_ORDER)


def uninstall(name):
    """Delete one theme's config resource (and its files) via
    system.config.delete(). Returns False if it was not installed rather
    than raising -- getResource() raises on missing, which is exactly how
    "not installed" is detected."""
    if name not in THEMES:
        raise ValueError("Unknown theme id '%s' -- refusing to touch" % name)
    try:
        res = system.config.getResource(
            moduleId="com.inductiveautomation.perspective",
            typeId="themes", name=name)
    except (Exception, Throwable):
        return False
    system.config.delete(
        moduleId="com.inductiveautomation.perspective",
        typeId="themes", name=name,
        signature=res.getSignature(), actor="theme-manager")
    return True


def uninstall_all():
    """Delete every embedded theme's config resource that is currently
    installed. Returns the list of ids actually removed."""
    removed = []
    for name in THEME_ORDER:
        if uninstall(name):
            removed.append(name)
    return removed


def install_some(names):
    """Install the named themes with one scan. Names outside THEMES are
    skipped, not raised: the selection can hold stock or user rows."""
    done = [n for n in THEME_ORDER if n in (names or [])]
    for name in done:
        _write_theme_files(name)
    if done:
        _rescan()
    return done


def uninstall_some(names):
    """Remove the named themes. Same whitelist as install_some()."""
    return [n for n in THEME_ORDER if n in (names or []) and uninstall(n)]


# ---- optional stock-theme update ----------------------------------------
# Installing the custom themes NEVER touches a stock theme. Separately and
# optionally, the four ON-DISK stock variants can take a small additions
# file (color-scheme + themed scrollbars) appended via one @import line at
# the end of their index.css -- their look is unchanged, and restoring is
# deleting that file and that line. light and dark live INSIDE the
# Perspective module jar: there are no files on disk to update, so they
# are never touched (pick light-cool / dark-cool to get the additions).

STOCK_BUILTIN = ["light", "dark"]
STOCK_UPDATABLE = ["light-cool", "light-warm", "dark-cool", "dark-warm"]
STOCK_ORDER = ["light", "light-cool", "light-warm",
               "dark", "dark-cool", "dark-warm"]
STOCK_DARK = {"light": False, "light-cool": False, "light-warm": False,
              "dark": True, "dark-cool": True, "dark-warm": True}
ADDITIONS_FILE = "theme-additions.css"
ADDITIONS_IMPORT = '@import "./theme-additions.css";'
# Written under a different name before v1.7.1. A gateway that ran
# "Update stock themes" on an older build still carries it, so both the
# file and its @import line are recognised and removed -- otherwise the
# rename strands a file that Restore can no longer see and stock_state
# reports "stock" for a theme that is still carrying additions.
LEGACY_ADDITIONS = ["gaskony-additions.css"]
LEGACY_IMPORTS = ['@import "./%s";' % n for n in LEGACY_ADDITIONS]
ADDITIONS_CSS = {
    False: "/* theme-additions.css -- written by the Theme Installer\n * (ignition-themes). ADDITIONS ONLY, the stock look is untouched:\n *   - color-scheme declaration (without it Chrome's auto dark mode\n *     repaints SVG fills client-side)\n *   - scrollbars follow the theme (stock themes leave them at the\n *     browser default)\n * Restore = delete this file and the import line at the end of\n * index.css -- the Restore button does exactly that. */\n:root { color-scheme: light; }\n* {\n  scrollbar-color: var(--border) transparent;\n  scrollbar-width: thin;\n}\n::-webkit-scrollbar { width: 10px; height: 10px; }\n::-webkit-scrollbar-track, ::-webkit-scrollbar-corner { background: transparent; }\n::-webkit-scrollbar-thumb {\n  background: var(--border);\n  border-radius: 6px;\n  border: 2px solid transparent;\n  background-clip: content-box;\n}\n",
    True: "/* theme-additions.css -- written by the Theme Installer\n * (ignition-themes). ADDITIONS ONLY, the stock look is untouched:\n *   - color-scheme declaration (without it Chrome's auto dark mode\n *     repaints SVG fills client-side)\n *   - scrollbars follow the theme (stock themes leave them at the\n *     browser default)\n * Restore = delete this file and the import line at the end of\n * index.css -- the Restore button does exactly that. */\n:root { color-scheme: dark; }\n* {\n  scrollbar-color: var(--border) transparent;\n  scrollbar-width: thin;\n}\n::-webkit-scrollbar { width: 10px; height: 10px; }\n::-webkit-scrollbar-track, ::-webkit-scrollbar-corner { background: transparent; }\n::-webkit-scrollbar-thumb {\n  background: var(--border);\n  border-radius: 6px;\n  border: 2px solid transparent;\n  background-clip: content-box;\n}\n",
}


def _read(path):
    fh = open(path, "rb")
    try:
        return fh.read().decode("utf-8")
    finally:
        fh.close()


def _write(path, text):
    fh = open(path, "wb")
    try:
        fh.write(text.encode("utf-8"))
    finally:
        fh.close()


def _stock_rewrite_manifest(theme_dir):
    """resource.json must list the files actually in the directory (and
    the now-stale signature must go, the same unstamped way the custom
    themes ship -- the scan re-stamps it). The description survives."""
    path = os.path.join(theme_dir, "resource.json")
    doc = {"scope": "G", "version": 1, "restricted": False,
           "overridable": True, "attributes": {}}
    try:
        old = json.loads(_read(path))
        if old.get("description"):
            doc["description"] = old["description"]
    except (Exception, Throwable):
        pass
    doc["files"] = [n for n in sorted(os.listdir(theme_dir))
                    if n != "resource.json"]
    _write(path, json.dumps(doc, indent=2))


def stock_state(name):
    """'builtin' (jar-served, never touched) | 'missing' (not on this
    gateway) | 'updated' (carries the additions) | 'stock'."""
    if name in STOCK_BUILTIN:
        return "builtin"
    d = os.path.join(_themes_root(), name)
    idx = os.path.join(d, "index.css")
    if not os.path.isfile(idx):
        return "missing"
    try:
        text = _read(idx)
    except (Exception, Throwable):
        return "missing"
    for filename, marker in ([(ADDITIONS_FILE, ADDITIONS_IMPORT)] +
                            zip(LEGACY_ADDITIONS, LEGACY_IMPORTS)):
        if marker in text and os.path.isfile(os.path.join(d, filename)):
            return "updated"
    return "stock"


def _stock_drop_legacy(d):
    """Remove a pre-1.7.1 additions file and its @import. Returns whether
    anything was there."""
    changed = False
    idx_path = os.path.join(d, "index.css")
    for filename in LEGACY_ADDITIONS:
        path = os.path.join(d, filename)
        if os.path.isfile(path):
            os.remove(path)
            changed = True
    if os.path.isfile(idx_path):
        idx = _read(idx_path)
        kept = [l for l in idx.splitlines()
                if l.strip() not in LEGACY_IMPORTS]
        if len(kept) != len(idx.splitlines()):
            _write(idx_path, "\n".join(kept) + "\n")
            changed = True
    return changed


def _stock_update_files(name):
    if name not in STOCK_UPDATABLE:
        raise ValueError("'%s' is not an updatable stock theme" % name)
    d = os.path.join(_themes_root(), name)
    if not os.path.isfile(os.path.join(d, "index.css")):
        return False    # variant absent on this gateway -- skip, not an error
    _stock_drop_legacy(d)
    _write(os.path.join(d, ADDITIONS_FILE), ADDITIONS_CSS[STOCK_DARK[name]])
    idx_path = os.path.join(d, "index.css")
    idx = _read(idx_path)
    if ADDITIONS_IMPORT not in idx:
        # index.css is @import lines only, so one more AT THE END is valid
        # css and the gateway flattener inlines it after everything stock.
        if not idx.endswith("\n"):
            idx += "\n"
        _write(idx_path, idx + ADDITIONS_IMPORT + "\n")
    _stock_rewrite_manifest(d)
    return True


def _stock_restore_files(name):
    if name not in STOCK_UPDATABLE:
        raise ValueError("'%s' is not an updatable stock theme" % name)
    d = os.path.join(_themes_root(), name)
    idx_path = os.path.join(d, "index.css")
    changed = False
    add_path = os.path.join(d, ADDITIONS_FILE)
    if os.path.isfile(add_path):
        os.remove(add_path)
        changed = True
    if _stock_drop_legacy(d):
        changed = True
    if os.path.isfile(idx_path):
        idx = _read(idx_path)
        if ADDITIONS_IMPORT in idx:
            kept = [l for l in idx.splitlines()
                    if l.strip() != ADDITIONS_IMPORT]
            _write(idx_path, "\n".join(kept) + "\n")
            changed = True
    if changed:
        _stock_rewrite_manifest(d)
    return changed


def stock_update_all():
    """Add the additions to every on-disk stock variant, then ONE scan.
    Safe to re-run (idempotent); their look does not change."""
    updated = [n for n in STOCK_UPDATABLE if _stock_update_files(n)]
    if updated:
        _rescan()
    return updated


def stock_restore_all():
    """Put every updated stock variant back exactly as stock."""
    restored = [n for n in STOCK_UPDATABLE if _stock_restore_files(n)]
    if restored:
        _rescan()
    return restored


def status():
    """Custom rows ({kind: "custom", installed}) in THEME_ORDER, then
    stock rows ({kind: "stock", stock: stock_state}) in STOCK_ORDER,
    for the Installer view's table."""
    installed = set()
    try:
        for res in system.config.getResources(
                moduleId="com.inductiveautomation.perspective", typeId="themes"):
            installed.add(str(res.getName()))
    except (Exception, Throwable):
        pass
    out = []
    for name in THEME_ORDER:
        theme = THEMES[name]
        out.append({
            "id": name,
            "label": theme["label"],
            "dark": theme["dark"],
            "kind": "custom",
            "installed": name in installed,
        })
    for name in STOCK_ORDER:
        out.append({
            "id": name,
            "label": name.replace("-", " ").capitalize(),
            "dark": STOCK_DARK[name],
            "kind": "stock",
            "stock": stock_state(name),
        })
    # Themes somebody made on the Customise page. Neither list
    # knew about them, so creating one put it on no page at all.
    imported = set(imported_themes())
    for name in user_themes():
        out.append({
            "id": name,
            "label": name,
            "dark": user_base_of(name) == "dark",
            "kind": "imported" if name in imported else "user",
            "installed": name in installed,
        })
    return out

# ---------------------------------------------------------------------------
# INSIGHT -- what these themes actually change.
#
# Hand-authored, commit-tracked, appended verbatim to themepack/code.py by
# build_installer.py (same pattern as selector-popup/). Everything below reads
# the LIVE gateway, never a figure baked in at build time: a page that quotes
# build-time numbers is a document that goes stale silently, and the whole
# point of these pages is to show what is actually installed right now.
# ---------------------------------------------------------------------------

_VAR_RE = re.compile(r'^[ \t]*(--[A-Za-z0-9_-]+)[ \t]*:[ \t]*([^;]+);', re.M)
_CLASS_RE = re.compile(r'^\.psc-st\\/([A-Za-z0-9/\\_-]+?)\.psc-st\\/', re.M)

# What a theme is built out of. index.css is literally three lines, and that
# is the honest answer to "what is going on": we do not replace Ignition's
# theme, we import it and then override on top.
LAYERS = [
    ("Ignition's own theme", "index.css imports light or dark from the "
     "Perspective module. Everything we do not name keeps working because "
     "this layer is still underneath it."),
    ("variables.css", "Re-points Ignition's OWN variable names at the pack's "
     "palette. This is why stock components restyle without being touched "
     "individually."),
    ("globals.css", "The part with no stock equivalent: scrollbars, "
     "compensation for colours Ignition hard-codes, the --st-* tokens, "
     "component chrome, and the st/... class contract."),
]


# ---------------------------------------------------------------------------
# Making the lists readable.
#
# The first version of these pages listed 110 variables alphabetically --
# --arrow-color, --black, --border, --borderRadius -- with a "state" column
# saying "overridden". Every fact on the page was true and none of it was
# clear: an alphabetical list of Ignition's internal variable names tells a
# first-time reader nothing about what the theme actually does to their
# screens. Grouping by what a variable AFFECTS is the difference between a
# reference and an explanation.
# ---------------------------------------------------------------------------

# Ordered: what somebody wants to know first comes first. A variable lands in
# the first group whose pattern matches, so order is also precedence.
GROUPS = [
    ("Page and card surfaces",
     r'^--(containerRoot|container|containerNested|contextBackground|'
     r'tooltip-background-color|neutral-([1-8]0))$'),
    ("Text and icons",
     r'^--(label|icon|arrow-color|neutral-(90|100))'),
    ("Accent and buttons",
     r'^--(callToAction|indicator)'),
    ("Borders and corners",
     r'^--(border|containerBorder)'),
    ("Inputs and controls",
     r'^--(input|checkbox|radio|toggleSwitch|defaultSlider)'),
    ("Status colours",
     r'^--(error|warning|success|info)'),
    ("Depth and shadows",
     r'^--boxShadow'),
    ("Progress bars",
     r'^--progress'),
    ("P&ID symbols and pipes",
     r'^--(symbol|pipe)'),
    ("Chart palettes",
     r'^--(qual|seq|div)-'),
]

TOKEN_GROUPS = [
    ("Page and surfaces", r'^--st-(page|card|topbar|sidebar)'),
    ("Text", r'^--st-(fg|chrome-fg|on-accent)$'),
    ("Accent", r'^--st-accent$'),
    ("Buttons", r'^--st-btn-'),
    ("Tables", r'^--st-(head|cell|row|table)'),
    ("Inputs", r'^--st-input'),
    ("Tabs and navigation", r'^--st-(tab|nav)'),
    ("Borders", r'^--st-(chrome-border|.*-border)$'),
    ("Type and spacing", r'^--st-(.*-font|.*-pad|row-min)$'),
]

# Expanded for readability. These are the abbreviations in our OWN token
# names, so this is a lookup, not a guess about someone else's naming.
WORDS = {
    "st": "", "btn": "button", "dan": "danger", "gho": "ghost",
    "pri": "primary", "bg": "background", "fg": "text", "head": "table header",
    "chrome": "sidebar and header", "nav": "navigation", "pad": "padding",
    "fx": "effect", "min": "minimum height", "solid": "(opaque)",
    "tab": "tab", "row": "table row", "cell": "table cell",
    "chip": "identity chip", "brand": "brand", "group": "group heading",
    "rule": "divider", "card": "card", "page": "page", "topbar": "top bar",
    "sidebar": "sidebar", "input": "input", "table": "table",
    "accent": "accent", "border": "border", "active": "selected",
    "inactive": "unselected", "on": "text on the", "font": "font size",
}

_COLOUR_RE = re.compile(r'^(#[0-9A-Fa-f]{3,8}|rgba?\(|hsla?\()')
_NOISE_RE = re.compile(r'\s*\((?:token|ref):[^)]*\)\s*$')


def group_of(name, groups):
    for label, pattern in groups:
        if re.search(pattern, name):
            return label
    return "Everything else"


def is_colour(value):
    """Whether a value can be painted as a swatch.

    Deliberately strict: a var(--x) reference, a shadow, a length or the
    keyword transparent all fail, and a swatch of a value that is not a colour
    is worse than no swatch -- it renders as an empty box that reads as a bug.
    """
    return bool(value and _COLOUR_RE.match(value.strip()))


def swatch(value):
    """A colour chip for a table cell.

    Inset and rounded, not a full-bleed cell: three white values in a row
    painted edge to edge merge into one white block, and a column that reads
    as one block for three different tokens is not showing you three colours.
    The border keeps a white or near-black chip visible against the surface
    it sits on.
    """
    if not is_colour(value):
        return {"value": "", "style": {}}
    return {"value": "", "style": {
        "backgroundColor": value.strip(),
        "margin": "5px 8px", "borderRadius": "3px",
        "borderStyle": "solid", "borderWidth": "1px",
        "borderColor": "var(--border)"}}


LIMIT = 150


def plain(name, comment=""):
    """A human sentence for one variable.

    Prefers the derivation build_theme.py recorded, minus its machine suffix:
    `(token:surface.page)` and `(ref:--border)` are for us, not for a reader
    meeting these themes for the first time. Falls back to expanding our own
    abbreviations for the --st-* tokens, which carry no comment at all.
    """
    if comment:
        text = _NOISE_RE.sub("", comment).strip()
        if len(text) > LIMIT:
            text = text[:LIMIT].rsplit(" ", 1)[0] + " ..."
        return text
    parts = [p for p in name.lstrip("-").split("-") if p and p != "st"]
    if len(parts) == 3 and parts[0] == "btn":
        # btn-dan-bg reads "Danger button background", not "Button danger
        # background": the variant qualifies the noun, it does not follow it.
        return ("%s button %s" % (WORDS.get(parts[1], parts[1]),
                                  WORDS.get(parts[2], parts[2]))).capitalize()
    words = [WORDS.get(part, part) for part in parts]
    return " ".join(w for w in words if w).strip().capitalize()


def _gateway_port():
    """This gateway's own HTTP port, read from data/gateway.xml.

    Never hardcoded. The resolved CSS is only reachable over HTTP -- the base
    light/dark sheets live inside the Perspective module, not on disk -- so a
    gateway on a non-default port would fail the fetch, and a failed fetch
    read as an empty base would report every single variable as "added by us".
    Wrong in the most flattering possible direction, which is the kind of
    wrong worth engineering against.
    """
    try:
        handle = open(os.path.join(_data_dir(), "gateway.xml"))
        try:
            xml = handle.read()
        finally:
            handle.close()
        found = re.search(r'"gateway\.port"\s*>\s*(\d+)', xml)
        if found:
            return int(found.group(1))
    except (Exception, Throwable):
        pass
    return 8088


def theme_css(theme_id):
    """The fully resolved stylesheet the browser actually receives.

    Not our source files: this is post-@import, exactly what is served, so it
    includes the base theme we build on and reflects any local edit somebody
    made to the installed copy.
    """
    return system.net.httpGet("http://localhost:%d/data/perspective/themes/%s.css"
                              % (_gateway_port(), theme_id))


def _vars_of(css):
    """Every custom property the sheet ends up defining. LAST definition wins.

    Last-wins is not a detail, it is the measurement. Our variables.css is
    imported after the base, so reading first-wins reports zero overrides and
    makes the themes look like they change nothing at all. That is exactly
    what the first version of this said.
    """
    found = {}
    for match in _VAR_RE.finditer(css):
        found[match.group(1)] = match.group(2).strip()
    return found


def _reasons(theme_id):
    """The generated 'why' comment beside each variable in our own source.

    build_theme.py writes a derivation next to every value it emits
    (`--containerRoot: #2e3540; /* page background, flattened over white
    (token:surface.page) */`). Those comments are stripped from what the
    browser gets, so they are read from the embedded copy instead -- which
    also means the reason still shows for a theme that is not installed.
    """
    out = {}
    theme = THEMES.get(theme_id)
    if not theme:
        return out
    source = theme["files"].get("variables.css", "") + theme["files"].get("globals.css", "")
    for line in source.split("\n"):
        match = re.match(r'^\s*(--[A-Za-z0-9_-]+)\s*:[^;]*;\s*/\*\s*(.*?)\s*\*/\s*$', line)
        if match:
            out[match.group(1)] = match.group(2)
    return out


def base_of(theme_id):
    """Which stock theme this one is built on, or "" if it IS one.

    light and dark are the bases. Returning themselves made "its own base
    theme" a comparison of a theme against itself, which reported 0 repainted
    and 120 identical under a headline saying light is built on light.
    """
    if theme_id in STOCK_BUILTIN:
        return ""
    theme = THEMES.get(theme_id)
    if theme:
        if re.search(r'@import\s+"\.\./dark/', theme["files"].get("index.css", "")):
            return "dark"
        return "light"
    return "dark" if STOCK_DARK.get(theme_id) else "light"


def compare(theme_id, against=None):
    """Row per custom property: what we inherit, override, and add.

    `against` defaults to the stock theme this one is built on, which is the
    comparison that answers "what did you change". Passing another theme id
    answers "how do these two differ", using the identical machinery.
    """
    if against is None:
        against = base_of(theme_id)
    if not against:
        return []          # a base theme with nothing behind it -- see headline()
    ours = _vars_of(theme_css(theme_id))
    theirs = _vars_of(theme_css(against))
    why = _reasons(theme_id)

    rows = []
    for name in sorted(set(ours) | set(theirs)):
        mine, other = ours.get(name), theirs.get(name)
        if mine is None:
            continue          # only in the comparison: not a change WE made
        if other is None:
            state = "new"
        elif mine == other:
            state = "kept as Ignition's"
        else:
            state = "repainted"
        rows.append({
            "kind": "variable",
            "group": group_of(name, GROUPS),
            "variable": name,
            "what": plain(name, why.get(name, "")),
            "swatch": swatch(mine),
            "value": mine,
            "compared": other or "-",
            "state": state,
        })
    # Grouped, in the order GROUPS declares. Alphabetical was the whole
    # problem: it interleaves chart palettes with page surfaces.
    # Rules FIRST. They are few, they are the part no variables list can show,
    # and in the case that prompted them -- an updated stock theme against the
    # original -- they are the entire answer: sorted last, the only difference
    # between the two sat below 120 identical rows and looked like nothing.
    order = dict((label, i) for i, (label, _) in enumerate(GROUPS))
    rows.sort(key=lambda r: (order.get(r["group"], len(order)), r["variable"]))
    return rule_rows(theme_id, against) + rows


def summary(theme_id, against=None):
    """The headline counts, and the layer breakdown beside them."""
    rows = [r for r in compare(theme_id, against) if r.get("kind") != "rule"]
    counts = {"inherited": 0, "overridden": 0, "added": 0}
    tally = {"kept as Ignition's": "inherited", "repainted": "overridden",
             "new": "added"}
    for row in rows:
        key = tally.get(row["state"])
        if key:
            counts[key] += 1
    theme = THEMES.get(theme_id, {"files": {}})
    globals_css = theme["files"].get("globals.css", "")
    counts["base"] = against or base_of(theme_id)
    # A caption of "of Ignition's variables repainted" is only true against
    # the stock base; comparing two custom themes it must name the other
    # theme instead of Ignition.
    other = label_of(against)
    if other:
        counts["cap_overridden"] = "differ from %s" % other
        counts["cap_inherited"] = "identical in both"
        counts["cap_added"] = "only in this theme"
    else:
        counts["cap_overridden"] = "of Ignition's variables repainted"
        counts["cap_inherited"] = "left exactly as Ignition set them"
        counts["cap_added"] = "new variables this theme adds"
    counts["total"] = len(rows)
    counts["tokens"] = len([r for r in rows if r["variable"].startswith("--st-")])
    counts["classes"] = len(set(_CLASS_RE.findall(globals_css)))
    return counts


_RULE_RE = re.compile(r'([^{}]+)\{([^}]*)\}', re.M)


def _token_users(css):
    """token -> the selectors in this theme that actually consume it.

    The --st-* tokens carry no derivation comment (unlike the variables.css
    values, which do), so there is no "why" to quote for them. Rather than
    ship a column that is empty on every row, this answers the question a
    reader actually has -- "what does this token affect?" -- by reading the
    theme's own rules. Measured from the artefact, so it cannot describe a use
    the theme does not have.
    """
    users = {}
    for match in _RULE_RE.finditer(css):
        group = " ".join(match.group(1).split())
        if group.startswith("@") or group == ":root":
            continue
        # One rule can carry a comma-separated selector GROUP. Count the
        # selectors, not the rules: a count of 3 printed beside six visible
        # selectors reads as a bug in the page.
        selectors = [sel.strip() for sel in group.split(",") if sel.strip()]
        for token in set(re.findall(r'var\((--st-[a-z0-9-]+)', match.group(2))):
            users.setdefault(token, []).extend(selectors)
    return users


# What a selector is TALKING ABOUT, in words. The raw text is unusable on a
# page meant for a first-time reader: one --st-sidebar-solid consumer is
# `ia_popup:has(> .body-wrapper > .popup-body > [class*="/containers/page"]) >
# .popup-header`, which is correct, precise, and tells nobody anything. Order
# matters -- the contract class is the most specific answer, so it wins.
PLACES = [
    (r'/containers/page', "page containers"),
    (r'/containers/card', "cards"),
    (r'/tables/', "tables"),
    (r'/buttons/danger', "danger buttons"),
    (r'/buttons/primary', "primary buttons"),
    (r'/buttons/ghost', "ghost buttons"),
    (r'/buttons/', "buttons"),
    (r'/text/brand', "the brand mark"),
    (r'/nav/', "navigation items"),
    (r'/inputs/', "inputs"),
    (r'psc-st-shell', "the app shell"),
    (r'ia_popup|popup-', "popups"),
    (r'ia_tabContainer|tab-menu', "tab strips"),
    (r'ia_pager', "table pagers"),
    (r'ia_table', "tables"),
    (r'scrollbar', "scrollbars"),
    (r'\bbutton\b', "buttons"),
    (r'ia_label', "labels"),
]


def _readable(selector):
    """One selector, as the thing it styles."""
    for pattern, place in PLACES:
        if re.search(pattern, selector):
            return place
    # Nothing recognised: fall back to the bare class name rather than the
    # whole selector chain, which is what made this column unreadable.
    bare = re.findall(r'[.#]([A-Za-z][A-Za-z0-9_-]+)', selector.replace("\\", ""))
    if not bare:
        return selector[:40]
    # `ia_dropdown__option--selected` is a class name, not a description.
    name = re.sub(r'^ia_', '', bare[-1])
    name = re.sub(r'--.*$', '', name)
    name = re.sub(r'__', ' ', name)
    return re.sub(r'(?<=[a-z])(?=[A-Z])', ' ', name).lower()


def contract(theme_id, css=None):
    """The --st-* tokens a project can rely on, with their live values.

    `css` overrides where they are read from. The Customise page passes a
    stylesheet with the theme's own files appended, because a theme copied a
    second ago is not being served yet and the pane was empty for exactly the
    theme somebody had just made.
    """
    if css is None:
        css = theme_css(theme_id)
    ours = _vars_of(css)
    users = _token_users(css)
    why = _reasons(theme_id)
    rows = []
    for name in sorted(ours):
        if not name.startswith("--st-"):
            continue
        seen, where = set(), []
        for sel in users.get(name, []):
            place = _readable(sel)
            if place not in seen:
                seen.add(place)
                where.append(place)
        shown = ", ".join(where[:4])
        if len(where) > 4:
            shown += " (+%d more)" % (len(where) - 4)
        rows.append({
            "group": group_of(name, TOKEN_GROUPS),
            "token": name,
            "what": plain(name, why.get(name, "")),
            "swatch": swatch(ours[name]),
            "value": ours[name],
            "where": shown or "-",
        })
    order = dict((label, i) for i, (label, _) in enumerate(TOKEN_GROUPS))
    rows.sort(key=lambda r: (order.get(r["group"], len(order)), r["token"]))
    return rows


def contract_classes(theme_id, css=None):
    """Every st/... class this theme publishes, and what each one sets.

    Read out of the theme's own globals.css rather than a list kept beside it,
    so the page cannot claim a class the theme does not actually ship.

    `css` overrides the source. Without it this answered from THEMES alone, so
    a theme made on the Customise page -- which carries the same 69 classes it
    was copied from -- was reported as publishing none.
    """
    if css is None:
        theme = THEMES.get(theme_id)
        if not theme:
            return []
        css = theme["files"].get("globals.css", "")
    rows = []
    for match in re.finditer(
            r'^\.psc-st\\/([A-Za-z0-9/\\_-]+?)\.psc-st\\/[A-Za-z0-9/\\_-]+?\s*\{([^}]*)\}',
            css, re.M):
        name = match.group(1).replace("\\", "")
        sets = []
        for decl in match.group(2).split(";"):
            if ":" in decl:
                sets.append(decl.split(":", 1)[0].strip())
        rows.append({
            "family": name.split("/")[0],
            "klass": "st/" + name,
            "sets": ", ".join(sets),
            "count": len(sets),
        })
    return sorted(rows, key=lambda r: r["klass"])


def layers(theme_id):
    """The three-layer anatomy, with this theme's real numbers attached."""
    counts = summary(theme_id)
    theme = THEMES.get(theme_id, {"files": {}})
    detail = [
        "%s -- inherited untouched by this theme: %d of %d variables"
        % (counts["base"], counts["inherited"], counts["total"]),
        "%d variables overridden, %d lines"
        % (counts["overridden"], len(theme["files"].get("variables.css", "").split("\n"))),
        "%d --st-* tokens, %d st/... classes, %d lines"
        % (counts["tokens"], counts["classes"],
           len(theme["files"].get("globals.css", "").split("\n"))),
    ]
    return [{"layer": LAYERS[i][0], "what": LAYERS[i][1], "here": detail[i]}
            for i in range(3)]


def label_of(theme_id):
    """A readable name for any theme id, custom or stock.

    THEMES only holds the ten this project installs, so looking a comparison
    up there alone returns nothing for Ignition's own six -- which is exactly
    how the tiles kept their stock captions while comparing against light-cool.
    """
    if not theme_id:
        return ""
    theme = THEMES.get(theme_id)
    if theme:
        return theme.get("label", theme_id)
    pretty = theme_id.replace("-", " ")
    if theme_id in STOCK_ORDER:
        return "Ignition " + pretty
    # Not ours and not Ignition's: name it, claim nothing about it.
    return pretty


def headline(theme_id, against=None):
    """The plain-English answer, in one sentence, with the real numbers in it.

    Two sentences, because there are two questions. With no comparison chosen
    the question is "what did you change from stock", and the answer names the
    base this theme is genuinely built on. With one chosen it is "how do these
    two differ" -- and the sentence must NOT say "built on", which it did:
    picking Ignition light cool made Glass Violet claim to be built on it.
    """
    counts = summary(theme_id, against)
    label = label_of(theme_id)
    if against and against != theme_id:
        other = label_of(against)
        return ("%s against %s: %d variables differ, %d are identical in both, "
                "and %d exist only in %s."
                % (label, other, counts["overridden"], counts["inherited"],
                   counts["added"], label))
    if theme_id in STOCK_BUILTIN and not against:
        return ("%s is one of Ignition's two base themes. It is served from "
                "inside the Perspective module rather than from a file on the "
                "gateway, so nothing -- this project included -- can modify it, "
                "and it has no base of its own to be compared against. Pick a "
                "theme on the right to compare it with. (The four stock "
                "variants ARE files, and CAN carry the optional additions -- "
                "try Ignition light cool.)" % label_of(theme_id))
    if against == theme_id:
        return ("%s compared with itself -- every one of its %d variables is "
                "identical, which is the only honest answer to that question."
                % (label, counts["total"]))
    return ("%s is built on Ignition's %s theme and repaints it: %d of its "
            "variables carry this pack's values, %d are left exactly as "
            "Ignition set them, and %d are new. Nothing is replaced wholesale "
            "-- anything the theme never names behaves as stock."
            % (label, base_of(theme_id), counts["overridden"],
               counts["inherited"], counts["added"]))


def _rules_of(css):
    """selector -> the declarations it sets, for every rule in the sheet.

    Variables were only ever half the story. `theme-additions.css` adds a
    color-scheme declaration and scrollbar rules and NOT ONE custom property,
    so a variables-only diff of an updated stock theme against the original is
    empty -- which reads as "nothing changed" when the truth is "the thing that
    changed is not a variable".
    """
    rules = {}
    for match in _RULE_RE.finditer(css):
        group = " ".join(match.group(1).split())
        if group.startswith("@"):
            continue
        props = []
        for decl in match.group(2).split(";"):
            if ":" in decl:
                props.append(decl.split(":", 1)[0].strip())
        if not props:
            continue
        for selector in [x.strip() for x in group.split(",") if x.strip()]:
            rules.setdefault(selector, set()).update(props)
    return rules


# Selector families the variables table has no way to describe. Checked before
# PLACES so scrollbars and the colour-scheme declaration -- the whole content
# of the stock additions -- are named as themselves.
RULE_PLACES = [
    (r'scrollbar', "Scrollbars"),
    (r'^:root$', "Colour scheme and root tokens"),
    # The contract classes escape their slashes, so the bare-class fallback
    # reduced all 72 of them to the meaningless stem "Psc-st".
    (r'psc-st\\?/', "Style contract classes"),
]


def _rule_place(selector, props=()):
    """Where a rule belongs, by selector -- or by what it SETS when the
    selector is too generic to say. `* { scrollbar-color; scrollbar-width }`
    is a scrollbar rule; filed under its selector it reads "Rules -- *".
    """
    for pattern, place in RULE_PLACES:
        if re.search(pattern, selector):
            return place
    if props and all(p.startswith("scrollbar") for p in props):
        return "Scrollbars"
    if selector in ("*", "*, *::before, *::after"):
        return "Everything on the page"
    return _readable(selector).capitalize()


def rule_rows(theme_id, against=None):
    """One row per area whose RULES differ, not one per rule.

    A custom theme differs from stock by well over a thousand rules; listing
    them would bury the table it is meant to complete. Aggregating by what the
    rules target keeps it to a handful of rows and still answers the question
    the variables table cannot: what changed that is not a colour.
    """
    if against is None:
        against = base_of(theme_id)
    if not against:
        return []
    ours = _rules_of(theme_css(theme_id))
    theirs = _rules_of(theme_css(against))

    areas = {}
    for selector, props in ours.items():
        was = theirs.get(selector)
        if was == props:
            continue
        place = _rule_place(selector, props)
        entry = areas.setdefault(place, {"added": 0, "changed": 0, "props": set()})
        entry["added" if was is None else "changed"] += 1
        entry["props"].update(props if was is None else (props ^ was))
    for selector in theirs:
        if selector not in ours:
            place = _rule_place(selector, theirs[selector])
            entry = areas.setdefault(place, {"added": 0, "changed": 0,
                                             "props": set()})
            entry["removed"] = entry.get("removed", 0) + 1

    rows = []
    for place in sorted(areas):
        entry = areas[place]
        bits = []
        for kind in ("added", "changed", "removed"):
            if entry.get(kind):
                bits.append("%d %s" % (entry[kind], kind))
        props = sorted(p for p in entry["props"] if not p.startswith("--"))
        rows.append({
            "kind": "rule",
            "group": "Rules -- " + place,
            "variable": "%s rule(s)" % ", ".join(bits),
            "what": ", ".join(props[:8]) + (" ..." if len(props) > 8 else ""),
            "swatch": {"value": "", "style": {}},
            "value": "",
            "compared": "",
            "state": "added" if not entry.get("changed") else "repainted",
        })
    return rows

# ---------------------------------------------------------------------------
# EDITOR -- read and write the theme files on this gateway.
#
# Hand-authored, commit-tracked, appended verbatim to themepack/code.py by
# build_installer.py (same pattern as insight/ and selector-popup/).
#
# WHY THIS EXISTS. Ectobox ship a Designer module that does exactly this, and
# it is a good tool, but a module is not wanted for it. Their module is one
# RPC interface of eleven filesystem methods over the same directory this
# file resolves, with "refresh" being an ordinary config scan -- nothing that
# needs a JVM, a Designer, or a signed .modl. So it lives here instead, and
# ships with the project import that already installs the themes.
#
# WHAT IT IS NOT. It is not a themes BUILD tool. The ten packs are generated
# from packs/*.json by build_theme.py and embedded in THEMES above; editing a
# file here changes what is on THIS gateway and nothing in the repo. Reinstall
# from the Installer page and your edit is gone -- which is the correct
# behaviour for a live-editing tool, and the reason read_file() reports whether
# a file still matches what the installer would write.
#
# EVERY function here re-asserts that the path it is about to touch is inside
# the themes root. The guard is not "the caller already checked" -- these are
# reachable from a Perspective page, which is reachable by anyone who can open
# the project.
# ---------------------------------------------------------------------------

# resource.json is the config-resource MANIFEST, not theme content. It is
# rewritten from the directory listing on every save (_stock_rewrite_manifest),
# so hand-editing it is at best pointless and at worst strands a theme: a
# stale lastModificationSignature makes the scan reject the whole resource.
# The editor refuses to open it rather than letting someone learn that.
EDITOR_PROTECTED = ["resource.json"]

# What the editor will open. Anything else in a theme directory is listed but
# not editable -- a font or an image has no business in a text box.
EDITOR_TEXT_SUFFIXES = [".css", ".json", ".txt", ".md", ".svg"]

# A theme file we will not let a save empty. Every one of these is load-bearing:
# an empty index.css is a theme that silently stops importing Ignition's own,
# which looks like the gateway broke rather than like a bad edit.
EDITOR_NEVER_EMPTY = ["index.css", "config.json"]


def _editor_root():
    """The themes root, normalised, with a trailing separator -- the prefix
    every guarded path is tested against."""
    root = os.path.abspath(_themes_root())
    if not root.endswith(os.sep):
        root = root + os.sep
    return root


def _editor_resolve(theme, filename=None):
    """Resolve theme[/filename] INSIDE the themes root, or raise.

    Path traversal is checked after normalisation, on the absolute path, with a
    prefix test -- not by inspecting the input for '..'. A name that survives
    normalisation and still starts with the root is safe by construction; one
    that does not is refused whatever it looks like.
    """
    root = _editor_root()
    parts = [theme] if filename is None else [theme, filename]
    for part in parts:
        if not part or not isinstance(part, basestring):
            raise ValueError("Empty name -- refusing")
        if os.sep in part or (os.altsep and os.altsep in part):
            raise ValueError("'%s' is a path, not a name -- refusing" % part)
    path = os.path.abspath(os.path.join(root, *parts))
    if not (path + os.sep).startswith(root):
        raise ValueError("'%s' resolves outside the themes root -- refusing"
                         % os.path.join(*parts))
    return path


def _editor_is_text(filename):
    lowered = filename.lower()
    for suffix in EDITOR_TEXT_SUFFIXES:
        if lowered.endswith(suffix):
            return True
    return False


def list_themes():
    """Every theme directory ON DISK, with what we know about each.

    'ours' means the id is one of the ten this project can install, so the
    Installer page can overwrite it. A theme that is not ours is still fully
    editable -- that includes the four on-disk stock variants. light and dark
    are served from inside the Perspective module jar and have no directory, so
    they do not appear here at all and cannot be edited; that is not a gap this
    file can close.
    """
    root = _themes_root()
    rows = []
    if not os.path.isdir(root):
        return rows
    for name in sorted(os.listdir(root)):
        path = os.path.join(root, name)
        if not os.path.isdir(path):
            continue
        files = [f for f in sorted(os.listdir(path)) if f != "resource.json"]
        rows.append({
            "id": name,
            "ours": name in THEMES,
            "stock": name in STOCK_UPDATABLE,
            "files": len(files),
            "bytes": sum(os.path.getsize(os.path.join(path, f)) for f in files),
        })
    return rows


def list_files(theme):
    """The files in one theme directory. resource.json is listed, so the page
    can show it exists, but carries editable False."""
    d = _editor_resolve(theme)
    if not os.path.isdir(d):
        raise ValueError("No theme directory '%s' on this gateway" % theme)
    rows = []
    for name in sorted(os.listdir(d)):
        path = os.path.join(d, name)
        if not os.path.isfile(path):
            continue
        rows.append({
            "name": name,
            "bytes": os.path.getsize(path),
            "editable": _editor_is_text(name) and name not in EDITOR_PROTECTED,
            "protected": name in EDITOR_PROTECTED,
        })
    return rows


def read_file(theme, filename):
    """One file's text, plus whether it still matches what the installer would
    write for it.

    'modified' is the honest answer to "have I edited this?" and is None for a
    theme or file the installer does not ship -- absent, not false, because
    'not modified' would be a claim we cannot make about a file we have no
    reference copy of.
    """
    path = _editor_resolve(theme, filename)
    if not os.path.isfile(path):
        raise ValueError("No file '%s' in theme '%s'" % (filename, theme))
    if filename in EDITOR_PROTECTED:
        raise ValueError("'%s' is the resource manifest and is rewritten on "
                         "every save -- it is not editable" % filename)
    if not _editor_is_text(filename):
        raise ValueError("'%s' is not a text file" % filename)
    text = _read(path)
    shipped = None
    if theme in THEMES:
        shipped = THEMES[theme]["files"].get(filename)
    return {
        "theme": theme,
        "name": filename,
        "text": text,
        "bytes": len(text.encode("utf-8")),
        "modified": None if shipped is None else (text != shipped),
    }


def write_file(theme, filename, text, rescan=True):
    """Save one theme file, rewrite the manifest, and (by default) scan.

    The write is STAGED THEN RENAMED. A plain truncating write is a real hazard
    here and not a theoretical one: a config scan that reads a half-written
    file skips the resource silently and does not come back to it until
    something else in the directory changes. os.rename within one directory is
    atomic, so a reader sees either the old file or the new one.

    Pass rescan=False when saving several files in a row and scan once at the
    end -- a scan is not free, and one at the end is no less correct.
    """
    path = _editor_resolve(theme, filename)
    d = os.path.dirname(path)
    if not os.path.isdir(d):
        raise ValueError("No theme directory '%s' on this gateway" % theme)
    if filename in EDITOR_PROTECTED:
        raise ValueError("'%s' is the resource manifest and is rewritten on "
                         "every save -- it is not editable" % filename)
    if not _editor_is_text(filename):
        raise ValueError("'%s' is not a text file" % filename)
    if text is None:
        raise ValueError("No text to write")
    if filename in EDITOR_NEVER_EMPTY and not text.strip():
        raise ValueError("'%s' is load-bearing -- refusing to save it empty"
                         % filename)
    if filename.lower().endswith(".json"):
        # Fail before writing, not after the scan has rejected it. A theme
        # whose config.json will not parse is a theme that vanishes from the
        # picker with nothing on the page to say why.
        try:
            json.loads(text)
        except (Exception, Throwable) as e:
            raise ValueError("'%s' is not valid JSON: %s" % (filename, e))

    staged = path + ".editor-staged"
    _write(staged, text)
    if os.path.exists(path):
        os.remove(path)          # Jython on Windows will not rename onto an
                                 # existing name; harmless on Linux.
    os.rename(staged, path)

    _stock_rewrite_manifest(d)
    if rescan:
        _rescan()
    return {"theme": theme, "name": filename,
            "bytes": len(text.encode("utf-8"))}


def create_file(theme, filename, text=""):
    """Add a file to a theme directory. Refuses to overwrite."""
    path = _editor_resolve(theme, filename)
    if not os.path.isdir(os.path.dirname(path)):
        raise ValueError("No theme directory '%s' on this gateway" % theme)
    if os.path.exists(path):
        raise ValueError("'%s' already exists in '%s'" % (filename, theme))
    if not _editor_is_text(filename):
        raise ValueError("'%s' is not a text file name" % filename)
    if filename in EDITOR_PROTECTED:
        raise ValueError("'%s' is the resource manifest -- it is written for "
                         "you" % filename)
    return write_file(theme, filename, text)


def delete_file(theme, filename):
    """Remove a file from a theme directory and rewrite the manifest.

    index.css and config.json are refused: deleting either leaves a directory
    that still registers as a theme and then renders as a broken one.
    """
    path = _editor_resolve(theme, filename)
    if filename in EDITOR_PROTECTED or filename in EDITOR_NEVER_EMPTY:
        raise ValueError("'%s' cannot be deleted -- the theme needs it"
                         % filename)
    if not os.path.isfile(path):
        return False
    os.remove(path)
    _stock_rewrite_manifest(os.path.dirname(path))
    _rescan()
    return True


def revert_file(theme, filename):
    """Put back what the installer ships for one file. Only for our ten
    themes -- there is no reference copy of anyone else's."""
    if theme not in THEMES:
        raise ValueError("'%s' is not one of this project's themes -- there is "
                         "nothing to revert to" % theme)
    shipped = THEMES[theme]["files"].get(filename)
    if shipped is None:
        raise ValueError("The installer does not ship '%s' for '%s'"
                         % (filename, theme))
    return write_file(theme, filename, shipped)


def search(theme, needle, ignore_case=True):
    """Find a string across one theme's editable files.

    Plain substring, not regex: the thing anyone actually searches a theme for
    is a token name or a colour, and a regex box is a way to get a confusing
    error instead of an answer.
    """
    if not needle:
        return []
    d = _editor_resolve(theme)
    if not os.path.isdir(d):
        raise ValueError("No theme directory '%s' on this gateway" % theme)
    target = needle.lower() if ignore_case else needle
    hits = []
    for name in sorted(os.listdir(d)):
        if name in EDITOR_PROTECTED or not _editor_is_text(name):
            continue
        path = os.path.join(d, name)
        if not os.path.isfile(path):
            continue
        for number, line in enumerate(_read(path).split("\n"), start=1):
            haystack = line.lower() if ignore_case else line
            if target in haystack:
                hits.append({"file": name, "line": number,
                             "text": line.strip()[:200]})
    return hits


def search_all(needle, ignore_case=True):
    """The same search across every theme on the gateway -- the question
    'which themes still say this' is the one worth asking before an edit."""
    hits = []
    for row in list_themes():
        for hit in search(row["id"], needle, ignore_case):
            hit = dict(hit)
            hit["theme"] = row["id"]
            hits.append(hit)
    return hits


def refresh():
    """Ask the gateway to re-read the theme directories.

    This is the whole of Ectobox's "one-click refresh": an ordinary config
    scan. A saved file is already on disk -- this is what makes the gateway
    notice. write_file() does it for you; this is for after an edit made some
    other way, or to prove to yourself that the scan is what applies a change.
    """
    _rescan()
    return True


# ---------------------------------------------------------------------------
# TOKEN EDITING -- the part that is better than a text box.
#
# A theme's variables.css is a flat list of `--name: value;` declarations, and
# that is the file people actually want to change: the colours. Editing it as
# text means typing hex into a wall of CSS and finding out whether you got it
# right by looking at a page. Editing it as a FORM means a labelled row, a
# swatch you can see, and a colour picker.
#
# The raw text editor stays for index.css and globals.css, which are structure
# rather than values and have no useful form representation.
#
# These reuse the insight functions above -- GROUPS, group_of, is_colour,
# swatch, _VAR_RE -- on purpose. The grouping that explains a theme on the
# Themes page is the grouping that should order it in the editor; two different
# groupings of the same tokens would be two things to keep in step.
# ---------------------------------------------------------------------------

def tokens(theme, filename="variables.css"):
    """Every custom property THIS FILE declares, in file order, grouped.

    Deliberately the file's own declarations, not the resolved stylesheet:
    this is an editor, and you can only edit what is written here. A token the
    theme inherits from the base it imports is not in this list because
    changing it here would mean ADDING a declaration, which is a different
    action and gets its own button.

    Last-wins is reported as a duplicate rather than hidden -- two
    declarations of one token is nearly always a mistake, and silently showing
    only the winner is how it survives.
    """
    doc = read_file(theme, filename)
    text = doc["text"]
    seen = {}
    rows = []
    for match in _VAR_RE.finditer(text):
        name = match.group(1)
        value = match.group(2).strip()
        line = text.count("\n", 0, match.start()) + 1
        row = {
            "name": name,
            "value": value,
            "line": line,
            "group": group_of(name, GROUPS),
            "colour": is_colour(value),
            "swatch": swatch(value),
            "duplicate": name in seen,
        }
        seen[name] = True
        rows.append(row)

    # Grouped in the order GROUPS declares, file order within a group. The
    # alphabetical version of this list was unreadable for the same reason it
    # was unreadable on the Themes page.
    order = dict((label, i) for i, (label, _) in enumerate(GROUPS))
    rows.sort(key=lambda r: (order.get(r["group"], len(order)), r["line"]))
    return rows


def token_groups(theme, filename="variables.css"):
    """tokens() folded into [{group, rows}] -- what a Perspective repeater of
    sections binds to directly, so the view does no grouping of its own."""
    sections = []
    for row in tokens(theme, filename):
        if not sections or sections[-1]["group"] != row["group"]:
            sections.append({"group": row["group"], "rows": []})
        sections[-1]["rows"].append(row)
    for section in sections:
        section["count"] = len(section["rows"])
    return sections


def _token_replace(text, name, value):
    """Replace the value of the LAST declaration of one token, in place.

    Surgical on purpose. Regenerating the file from a parsed token list would
    lose every comment in it -- and our variables.css carries the generated
    'why' comment beside each variable, which is the only explanation of what
    the token is for. An editor that silently strips the documentation is
    worse than no editor.
    """
    last = None
    for match in _VAR_RE.finditer(text):
        if match.group(1) == name:
            last = match
    if last is None:
        raise ValueError("'%s' is not declared in this file" % name)
    # group(2) is the value between ':' and ';'. Splice around it rather than
    # rebuilding the line, so leading whitespace and any trailing comment on
    # the same line survive untouched.
    start = last.start(2)
    end = last.end(2)
    return text[:start] + value + text[end:]


def set_token(theme, value_map_or_name, value=None, filename="variables.css"):
    """Change one token, or several at once, and save.

    Two shapes because the page needs both: set_token(theme, '--border',
    '#4c566a') for a single picker commit, and set_token(theme, {'--border':
    '#4c566a', '--label': '#d8dee9'}) for a Save that collects a form. The
    batch does ONE write and ONE scan.
    """
    if isinstance(value_map_or_name, dict):
        changes = value_map_or_name
    else:
        if value is None:
            raise ValueError("No value for '%s'" % value_map_or_name)
        changes = {value_map_or_name: value}
    if not changes:
        return {"changed": 0}

    doc = read_file(theme, filename)
    text = doc["text"]
    for name in sorted(changes):
        new = changes[name]
        if new is None or not str(new).strip():
            raise ValueError("No value for '%s' -- a token with an empty value "
                             "is not the same as a token that is absent, and "
                             "reads as a broken theme" % name)
        if ";" in str(new) or "}" in str(new):
            raise ValueError("'%s' is not a single CSS value" % new)
        text = _token_replace(text, name, str(new).strip())

    write_file(theme, filename, text)
    return {"changed": len(changes), "tokens": sorted(changes)}


def add_token(theme, name, value, filename="variables.css"):
    """Declare a token the file does not currently declare.

    Appended inside the LAST rule in the file rather than at the end of the
    text, because a declaration after the closing brace is not in any rule and
    does nothing -- silently, which is the worst way for this to fail.
    """
    if not name.startswith("--"):
        raise ValueError("'%s' is not a custom property name" % name)
    doc = read_file(theme, filename)
    text = doc["text"]
    for match in _VAR_RE.finditer(text):
        if match.group(1) == name:
            raise ValueError("'%s' is already declared -- edit it instead"
                             % name)
    close = text.rfind("}")
    if close == -1:
        raise ValueError("'%s' has no CSS rule to add a declaration to"
                         % filename)
    line = "  %s: %s;\n" % (name, str(value).strip())
    text = text[:close] + line + text[close:]
    write_file(theme, filename, text)
    return {"name": name, "value": value}


def tokens_compared(theme, against=None, filename="variables.css"):
    """tokens(), plus what another theme says for the same token.

    This is what the retired "Under the hood" page did, folded into the place
    where you can act on it: seeing that --border is repainted is more useful
    beside the field that changes it than on a page of its own.

    `against` defaults to the stock theme this one is built on, which answers
    "what did we change". Pass another theme id to answer "how do these two
    differ". Same defaulting as compare(), on purpose -- one rule to remember.

    The comparison reads the other theme's RESOLVED stylesheet (post-@import),
    not its files, because the question is what the browser ends up with. Our
    own side stays the file's declarations: you can only edit what is written
    here.
    """
    rows = tokens(theme, filename)
    if against is None:
        against = base_of(theme)
    if not against:
        # A base theme with nothing behind it. Return the rows unmarked rather
        # than inventing a comparison -- see headline().
        for row in rows:
            row["compared"] = ""
            row["state"] = ""
        return rows
    try:
        theirs = _vars_of(theme_css(against))
    except (Exception, Throwable):
        # A comparison we could not fetch must not take the editor down with
        # it: the rows are still editable without it.
        for row in rows:
            row["compared"] = ""
            row["state"] = "compare unavailable"
        return rows
    for row in rows:
        other = theirs.get(row["name"])
        row["compared"] = other or "-"
        if other is None:
            row["state"] = "new"
        elif other == row["value"]:
            row["state"] = "same as %s" % against
        else:
            row["state"] = "differs"
    return rows


def compare_options(theme=None):
    """Theme ids to offer in the editor's 'compare against' picker, base
    first -- the default comparison should be the first thing in the list, not
    something to hunt for."""
    ids = [r["id"] for r in list_themes()]
    for builtin in STOCK_BUILTIN:
        if builtin not in ids:
            ids.append(builtin)   # jar-served: comparable, just not editable
    base = base_of(theme) if theme else ""
    ordered = ([base] if base and base in ids else [])
    ordered += [i for i in ids if i != base and i != theme]
    return ordered


# ---------------------------------------------------------------------------
# USER THEMES -- create and delete a theme of your own.
#
# The editor page manages user-customised themes of their own. The
# Installer's buttons deliberately refuse any id outside the ten this
# project carries, which is what makes them safe to press; so a theme
# somebody makes here needs its own create and delete, and those must
# refuse the packaged and stock ids just as firmly in the other direction.
#
# Three kinds of theme, and the kind decides what may be done to it:
#   packaged  one of ours -- edit it, revert it, but the Installer owns its
#             lifecycle. Delete belongs on the Installer's Remove button.
#   stock     Ignition's own. Editable (that is a gateway operator's business)
#             but never created or deleted by us.
#   user      made here. The only kind this section will delete.
# ---------------------------------------------------------------------------

# A theme id becomes a directory name and a URL segment. Anything outside this
# is refused rather than sanitised -- a sanitiser that turns "../x" into "x"
# has silently created a theme somewhere the caller did not ask for.
EDITOR_ID_RE = re.compile(r'^[a-z][a-z0-9]*(-[a-z0-9]+)*$')


def theme_kind(name):
    """'packaged' | 'stock' | 'user' | 'missing'."""
    if name in THEMES:
        return "packaged"
    if name in STOCK_BUILTIN or name in STOCK_UPDATABLE:
        return "stock"
    if os.path.isdir(os.path.join(_themes_root(), name)):
        return "user"
    return "missing"


def start_points():
    """What a new theme can be started FROM, best first.

    One list, because there was no honest way to choose between two buttons.
    "New theme" built on a stock base, which ships no --st-* tokens at all --
    so the theme you got had none of the vocabulary this page is organised
    around, and the natural first click was the wrong door. The ten come
    first; the stock bases stay, last and labelled, for someone who means it.
    """
    out = []
    for name in THEME_ORDER:
        out.append({"id": name, "label": "%s  (one of ours)" % name,
                    "kind": "ours"})
    for name in user_themes():
        out.append({"id": name, "label": "%s  (yours)" % name, "kind": "user"})
    for name in list(STOCK_BUILTIN) + list(STOCK_UPDATABLE):
        out.append({"id": name, "label": "%s  (bare Ignition theme)" % name,
                    "kind": "stock"})
    return out


def start_warning(source):
    """The line shown under the picker when the choice costs you something."""
    if theme_kind(source) == "stock":
        return ("A bare Ignition theme ships none of the --st-* tokens or "
                "st/... classes, so your theme would have no accent, no card "
                "colour and nothing for a project to build against. Start "
                "from one of ours unless you specifically want that.")
    return ""


def make_theme(name, source):
    """Create a theme, from whatever you chose to start from.

    Copying one of ours and building on a bare Ignition theme were two
    buttons that looked like alternatives and were not comparable: one gives
    you a whole theme, the other an empty shell. One entry point, one list,
    and the difference stated where the choice is made.
    """
    if theme_kind(source) == "stock":
        return new_theme(name, source)
    return copy_theme(source, name)


def user_themes():
    """Every theme on disk that is neither ours nor Ignition's, id-sorted.

    The Installer's status table lists the ten and the six; a theme somebody
    made here belonged to neither list and so appeared on neither page --
    you could create one and then not find it anywhere but the dropdown that
    made it.
    """
    out = []
    root = _themes_root()
    if not os.path.isdir(root):
        return out
    for name in sorted(os.listdir(root)):
        if not os.path.isdir(os.path.join(root, name)):
            continue
        if theme_kind(name) == "user":
            out.append(name)
    return out


def user_base_of(name):
    """'dark' or 'light' for a theme made here, read off its index.css.

    base_of() answers from THEMES and STOCK_DARK, so for a theme in neither it
    falls through to 'light' -- which labelled every copy of a dark theme
    Light in the status table.
    """
    try:
        text = read_file(name, "index.css")["text"]
    except (Exception, Throwable):
        return "light"
    return "dark" if re.search(r'@import\s+"\.\./dark/', text) else "light"


def _seed_variables(name, based_on, dark):
    """The starter variables.css: every variable the base declares, at the
    value it already has, grouped by what it affects.

    Read from the SERVED base stylesheet, because light and dark live inside
    the Perspective module and have no files to copy. If that read fails the
    file is still written, just without the list -- a theme with no starter
    values is worth less than one with them, but a create that fails outright
    is worth nothing.
    """
    head = ("/* %s -- your own theme, built on %s.\n"
            " * Every line below is what %s already says. Change one and only\n"
            " * that one changes; delete one and the base decides it again. */\n"
            % (name, based_on, based_on))
    body = ":root {\n  color-scheme: %s;\n" % ("dark" if dark else "light")
    try:
        values = _vars_of(theme_css(based_on))
    except (Exception, Throwable):
        values = {}
    rows = [(group_of(var, GROUPS), var, values[var]) for var in values]
    order = dict((label, i) for i, (label, _) in enumerate(GROUPS))
    rows.sort(key=lambda r: (order.get(r[0], len(order)), r[1]))
    last = None
    for group, var, value in rows:
        if group != last:
            body += "\n  /* %s */\n" % group
            last = group
        body += "  %s: %s;\n" % (var, value)
    return head + body + "}\n"


def new_theme(name, based_on="dark", description=""):
    """Create a theme of your own, built on a stock base like ours are.

    variables.css is seeded with the base's OWN values -- every variable it
    declares, at the value it already has. The theme therefore renders
    identically to the base, which is the point, but the page has a list to
    show and every line is yours to change.

    It is written fully populated rather than empty-but-for-a-comment: this
    page's whole proposition is a list of values you click, and an empty
    file would hand New theme a 550px void and a Save button with nothing
    to save. Empty is only defensible in a file editor, which this is not.

    globals.css stays empty. Its content is rules and classes, not values, and
    nothing on this page edits those except the Advanced text box.
    """
    if not name or not EDITOR_ID_RE.match(name):
        raise ValueError(
            "'%s' is not a usable theme id. Lower-case letters and digits, "
            "words joined by single hyphens -- for example 'ocean-dark'."
            % name)
    kind = theme_kind(name)
    if kind == "packaged":
        raise ValueError("'%s' is one of this project's own themes -- pick "
                         "another name" % name)
    if kind == "stock":
        raise ValueError("'%s' is one of Ignition's themes -- pick another "
                         "name" % name)
    if kind == "user":
        raise ValueError("'%s' already exists on this gateway" % name)

    bases = list(STOCK_BUILTIN) + list(STOCK_UPDATABLE)
    if based_on not in bases:
        raise ValueError("Build on one of: %s" % ", ".join(bases))

    theme_dir = _editor_resolve(name)
    os.makedirs(theme_dir)
    dark = STOCK_DARK.get(based_on, True)
    files = {
        "config.json": json.dumps(
            {"entrypoint": "index.css", "isPrivate": False}, indent=2) + "\n",
        "index.css": ('@import "../%s/index.css";\n'
                      '@import "./variables.css";\n'
                      '@import "./globals.css";\n' % based_on),
        # color-scheme is not optional and not decoration: without it Chrome's
        # auto dark mode repaints SVG fills client-side and charts come out
        # white on a dark page, with every server-side check reading correct.
        "variables.css": _seed_variables(name, based_on, dark),
        "globals.css": (
            "/* %s -- rules with no stock equivalent: scrollbars, component\n"
            " * chrome, the --st-* tokens and the st/... class contract.\n"
            " * Empty is fine; the base theme is still underneath. */\n"
            % name),
    }
    for filename, content in files.items():
        _write(os.path.join(theme_dir, filename), content)
    doc = {"scope": "G", "version": 1, "restricted": False,
           "overridable": True, "attributes": {},
           "files": sorted(files)}
    if description:
        doc["description"] = description
    else:
        doc["description"] = "%s -- created in the Theme Manager's editor" % name
    _write(os.path.join(theme_dir, "resource.json"), json.dumps(doc, indent=2))
    _rescan()
    return {"id": name, "based_on": based_on, "dark": dark}


def delete_theme(name):
    """Delete a theme made here. Refuses ours and Ignition's.

    Deletes the config resource AND the directory. system.config.delete on its
    own leaves the files, which the next scan reads straight back in -- the
    theme reappears and looks like the delete silently failed.
    """
    kind = theme_kind(name)
    if kind == "packaged":
        raise ValueError(
            "'%s' is one of this project's themes -- use Remove on the "
            "Installer page, which is the button that owns them" % name)
    if kind == "stock":
        raise ValueError("'%s' is one of Ignition's own themes and is never "
                         "deleted" % name)
    if kind == "missing":
        return False

    theme_dir = _editor_resolve(name)
    try:
        res = system.config.getResource(
            moduleId="com.inductiveautomation.perspective",
            typeId="themes", name=name)
        system.config.delete(
            moduleId="com.inductiveautomation.perspective",
            typeId="themes", name=name,
            signature=res.getSignature(), actor="theme-editor")
    except (Exception, Throwable):
        pass          # not registered; the directory removal below is the work
    if os.path.isdir(theme_dir):
        for entry in os.listdir(theme_dir):
            path = os.path.join(theme_dir, entry)
            if os.path.isfile(path):
                os.remove(path)
        os.rmdir(theme_dir)
    _rescan()
    return True


_GENERATED_HEADER = re.compile(r'\A\s*/\*.*?\*/\s*', re.S)


def _reheader(text, filename, source, name):
    """Replace a copied file's "DO NOT EDIT BY HAND" banner with the truth.

    That warning on every generated file makes it hard for people to change
    anything if they want to. On the ten themselves it is
    correct -- they are generated and Install overwrites them. On a COPY it is
    the opposite of correct: the copy is yours, nothing regenerates it, and
    carrying the banner over tells you not to do the one thing this page exists
    for. So the banner is rewritten, not stripped silently: the new header says
    where the file came from, which is the useful half of what it was saying.
    """
    if not filename.lower().endswith(".css"):
        return text
    match = _GENERATED_HEADER.match(text)
    body = text[match.end():] if (match and "DO NOT EDIT" in match.group(0)) \
        else text
    return ("/* %s -- YOUR COPY of %s, and yours to edit.\n"
            " * Nothing regenerates this file and Install does not overwrite\n"
            " * it. The original is generated from packs/%s.json in the\n"
            " * ignition-themes repo, which is why it says not to edit it.\n"
            " */\n" % (filename, source, source)) + body


def copy_theme(source, name):
    """Start a new theme from an existing one rather than from a bare base.

    The obvious way to make 'our nord-dark, but the accent is company red', and
    the reason the packaged themes stay safe to overwrite: copy first, edit the
    copy, and Install can still put ours back without touching yours.
    """
    if theme_kind(source) == "missing":
        raise ValueError("There is no theme '%s' on this gateway" % source)
    new_theme(name, based_on=base_of(source) or "dark",
              description="%s -- copied from %s" % (name, source))
    src_dir = _editor_resolve(source)
    dst_dir = _editor_resolve(name)
    copied = []
    for entry in sorted(os.listdir(src_dir)):
        if entry in EDITOR_PROTECTED or entry == "config.json":
            continue
        if not _editor_is_text(entry):
            continue
        text = _read(os.path.join(src_dir, entry))
        text = _reheader(text, entry, source, name)
        _write(os.path.join(dst_dir, entry), text)
        copied.append(entry)
    _stock_rewrite_manifest(dst_dir)
    _rescan()
    return {"id": name, "copied_from": source, "files": copied}


def base_options():
    """The stock themes a new theme can be built on."""
    return list(STOCK_BUILTIN) + list(STOCK_UPDATABLE)


# ---------------------------------------------------------------------------
# LIVE PREVIEW
#
# The customiser's whole premise is copy-one-and-tune-it, and tuning without
# seeing the result is guessing. The Installer's thumbnails are generated at
# BUILD time from the repo, so they cannot answer "what does it look like now
# that I changed the accent" -- this does, by reading the stylesheet the
# browser is actually being served and drawing the same mini screen from it.
#
# Same layout and the same palette keys as build_installer.py's preview_svg,
# deliberately: the picture on this page and the picture in the Installer's
# table have to be the same picture or neither can be trusted.
# ---------------------------------------------------------------------------

def _editor_declared(theme):
    """Every custom property the theme's OWN files declare, read off disk.

    The point is the timing. theme_css() fetches what the gateway is serving,
    which is the only way to see the base theme -- light and dark live inside
    the Perspective module, not on disk -- but it is a copy the gateway
    rebuilds after a scan, and a save beats the rebuild often enough that the
    preview showed the previous colour and looked broken. The files are
    authoritative the instant write_file() returns, so they go over the top.
    """
    values = {}
    for filename in EDITOR_COLOUR_FILES:
        try:
            values.update(_vars_of(read_file(theme, filename)["text"]))
        except (Exception, Throwable):
            continue                     # a theme need not have both files
    return values


def _colour_resolver(theme):
    """The theme's values, and a function that follows var() chains through
    them. Anything still unresolved comes back empty rather than literal: a
    var() reference painted as-is renders in the VIEWING page's colours and
    quietly shows the wrong thing.
    """
    values = {}
    try:
        values.update(_vars_of(theme_css(theme)))
    except (Exception, Throwable):
        # A theme made seconds ago is not being SERVED yet: the gateway 404s
        # its stylesheet until the scan lands and httpGet raises rather than
        # returning empty. Its BASE is already served and its own files are on
        # disk, so fall back to those -- otherwise everything downstream of
        # this (the preview picture, the swatch palette) is blank or in error
        # for the first half-minute of a theme's life, which is exactly when
        # somebody is looking at it.
        try:
            values.update(_vars_of(theme_css(user_base_of(theme))))
        except (Exception, Throwable):
            pass
    # Served copy for the inherited base, this theme's own files for anything
    # it sets itself -- so a save shows immediately instead of a scan later.
    values.update(_editor_declared(theme))

    return values, _resolver(values)


def _resolver(values):
    def resolve(value, hops=0):
        while value and value.startswith("var(") and hops < 6:
            found = re.match(r'var\(\s*(--[A-Za-z0-9_-]+)', value)
            if not found:
                return ""
            value = (values.get(found.group(1)) or "").strip()
            hops += 1
        return "" if (value or "").startswith("var(") else (value or "")
    return resolve


def live_palette(theme, values=None):
    """The dozen colours a preview is painted with, resolved from the LIVE
    stylesheet -- or from `values` when given, for a theme not installed."""
    if values is None:
        values, resolve = _colour_resolver(theme)
    else:
        resolve = _resolver(values)

    def pick(*names):
        for name in names:
            value = resolve((values.get(name) or "").strip())
            if value and value != "transparent":
                return value
        return ""

    page = pick("--st-page-solid", "--containerRoot")
    return {
        "page": page,
        "sidebar": pick("--st-sidebar-solid", "--containerNested", "--container"),
        "card": pick("--st-card", "--container"),
        "text": pick("--st-fg", "--label"),
        "muted": pick("--label--disabled", "--label"),
        "chromeFg": pick("--st-chrome-fg", "--label"),
        "accent": pick("--st-accent", "--callToAction"),
        "onAccent": pick("--st-on-accent") or "#ffffff",
        "border": pick("--st-chrome-border", "--border"),
        "headBg": pick("--st-head-solid", "--containerNested", "--container"),
        "headFg": pick("--st-head-fg", "--label"),
        "rowBg": pick("--st-row-bg") or page,
        "cellFg": pick("--st-cell-fg", "--label"),
    }


def live_preview_svg(theme, width=340, height=102, values=None):
    """The mini screen, drawn from live values, at whatever size is asked for."""
    pal = live_palette(theme, values)

    def c(key, fallback="#888888"):
        return pal.get(key) or fallback

    parts = ['<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" '
             'viewBox="0 0 200 60">' % (width, height)]

    def rect(x, y, w, h, fill, rx=0):
        parts.append('<rect x="%s" y="%s" width="%s" height="%s" fill="%s" '
                     'rx="%s"/>' % (x, y, w, h, fill, rx))

    rect(0, 0, 200, 60, c("page"))
    rect(0, 0, 200, 11, c("sidebar"))
    rect(0, 11, 26, 49, c("sidebar"))
    for i in range(3):
        rect(5, 18 + i * 5, 16, 2, c("chromeFg"), 1)
    rect(32, 16, 92, 26, c("card"), 2)
    rect(36, 20, 54, 3, c("text"), 1)
    rect(36, 26, 44, 2, c("muted"), 1)
    rect(36, 32, 30, 7, c("accent"), 2)
    rect(40, 35, 22, 2, c("onAccent"), 1)
    rect(130, 16, 64, 26, c("headBg"), 2)
    rect(130, 16, 64, 7, c("headBg"), 2)
    rect(133, 19, 26, 2, c("headFg"), 1)
    for i in range(2):
        rect(130, 25 + i * 8, 64, 7, c("rowBg"))
        rect(133, 28 + i * 8, 30, 2, c("cellFg"), 1)
    rect(5, 4, 34, 3, c("chromeFg"), 1)
    parts.append("</svg>")
    return "".join(parts)


def live_preview_uri(theme, width=340, height=102, values=None):
    """base64 rather than percent-encoding: the SVG carries #rrggbb by the
    dozen and a raw '#' truncates a url() at the first colour."""
    import base64
    svg = live_preview_svg(theme, width, height, values)
    return "data:image/svg+xml;base64," + base64.b64encode(
        svg.encode("utf-8")).decode("ascii")


# ---------------------------------------------------------------------------
# WHAT MAY BE CHANGED
#
# The ten pre-packaged themes are generated from packs/*.json and their files
# say DO NOT EDIT BY HAND, which is the truth: Install overwrites them. A page
# that invites you to edit one is inviting work that disappears at the next
# install, so the customiser offers a COPY instead and the ten stay read-only.
# ---------------------------------------------------------------------------

def about_text(theme):
    """The same facts as one block of text, one per line.

    A table charged 30px a row plus a 30px header strip for four short facts
    and still needed a scrollbar on a laptop. Lines in a label cost their line
    height and nothing else, and there is no empty header band over them.
    """
    return "\n".join("%s:  %s" % (r["fact"], r["detail"]) for r in about(theme))


def about(theme):
    """The handful of facts about a theme that are worth a line each.

    Replaces a 69-row list of st/... class names. Every one of the ten
    publishes the SAME class set -- verified by comparing the sorted class
    lists across finance-ledger, nord-dark, glass-violet, industrial-light and
    leather-dark: identical -- so listing them per theme answered one yes/no
    question with a scroll, and said nothing about the theme you were on.
    """
    rows = []
    kind = theme_kind(theme)
    base = user_base_of(theme) if kind == "user" else base_of(theme)
    rows.append({"fact": "Built on", "detail": base or "nothing -- it IS a base"})
    try:
        classes = editor_classes(theme)
    except (Exception, Throwable):
        classes = []
    if classes:
        rows.append({"fact": "Style classes",
                     "detail": "%d, the standard contract"
                               % len(classes)})
    else:
        rows.append({"fact": "Style classes",
                     "detail": "none -- a stock base ships none"})
    try:
        found = [r for r in list_themes() if r["id"] == theme]
    except (Exception, Throwable):
        found = []
    if found:
        rows.append({"fact": "Files",
                     "detail": "%d files, %d KB"
                               % (found[0]["files"], found[0]["bytes"] / 1024)})
    # How to USE it. The page never said, so you finished a theme and were on
    # your own: no mention of a project, a session or the Theme menu anywhere
    # on it. It is installed the moment it exists -- there is no publish step.
    rows.append({"fact": "To use it",
                 "detail": "the Theme menu above, or your project's "
                           "session props"})
    return rows


def editor_css(theme):
    """What the browser WILL get: the served stylesheet with this theme's own
    files appended, so the last save counts even before the scan does.

    Appended, not substituted: the base theme lives inside the Perspective
    module and is only ever visible through the served copy. _vars_of takes
    the last definition, which is the same rule the browser applies, so the
    disk copy wins where both say something.
    """
    parts = []
    try:
        parts.append(theme_css(theme))
    except (Exception, Throwable):
        pass
    for filename in EDITOR_COLOUR_FILES:
        try:
            parts.append(read_file(theme, filename)["text"])
        except (Exception, Throwable):
            continue
    return "\n".join(parts)


def editor_contract(theme):
    """contract(), answered for a theme that may be seconds old."""
    return contract(theme, editor_css(theme))


def editor_classes(theme):
    """contract_classes(), read from the theme's own globals.css on disk."""
    try:
        css = read_file(theme, "globals.css")["text"]
    except (Exception, Throwable):
        return contract_classes(theme)
    return contract_classes(theme, css)


def is_editable(theme):
    """Only a theme made here may be changed from here."""
    return theme_kind(theme) == "user"


def why_not_editable(theme):
    """The sentence the page shows instead of an editor, or '' when editable."""
    kind = theme_kind(theme)
    if kind == "user":
        return ""
    if kind == "packaged":
        return ("This is one of the ten themes the project ships. Its files "
                "are generated from the repo and Install puts them back, so a "
                "change made here would disappear the next time anyone "
                "pressed Install. Make a copy and the copy is yours.")
    if kind == "stock":
        return ("This is one of Ignition's own themes, shared by every "
                "project on this gateway, and an Ignition upgrade replaces "
                "it. Make a copy and the copy is yours.")
    return "There is no theme selected."


# ---------------------------------------------------------------------------
# EVERY colour, across both files.
#
# tokens() reads one file, and the customiser first shipped pointed at
# variables.css -- which is where Ignition's OWN variable names are re-pointed,
# but NOT where the theme's identity lives. The --st-* tokens are declared in
# globals.css, so "make the accent our company red" -- the single most likely
# reason to open this page -- was the one thing the colour list could not do.
# ---------------------------------------------------------------------------

EDITOR_COLOUR_FILES = ["globals.css", "variables.css"]


def all_tokens(theme):
    """Every custom property the theme declares, from every file it declares
    them in, each row saying WHICH file so a save edits the right one.

    globals.css first: the --st-* tokens are the theme's own vocabulary and the
    reason someone is here, where variables.css is mostly Ignition's names
    re-pointed at them.
    """
    rows = []
    for filename in EDITOR_COLOUR_FILES:
        try:
            found = tokens(theme, filename)
        except (Exception, Throwable):
            continue                     # a theme need not have both files
        try:
            why = _reasons(theme)
        except (Exception, Throwable):
            why = {}
        for row in found:
            row = dict(row)
            row["file"] = filename
            # What the value is FOR, in a sentence -- kept here rather than a
            # separate read-only pane, which would only repeat the same
            # --st-* names with their resolved values.
            row["what"] = plain(row["name"], why.get(row["name"], ""))
            # The --st-* tokens have their OWN grouping. Run through GROUPS
            # (which classifies Ignition's variable names) they all land in
            # "Everything else", which is the least useful thing a grouped
            # list can say about the theme's own vocabulary.
            if filename == "globals.css":
                row["group"] = group_of(row["name"], TOKEN_GROUPS)
            rows.append(row)
    return rows


def token_file(theme, name):
    """Which of the theme's files declares this token. Last file wins, the
    same way the browser resolves it."""
    where = ""
    for filename in EDITOR_COLOUR_FILES:
        try:
            for row in tokens(theme, filename):
                if row["name"] == name:
                    where = filename
        except (Exception, Throwable):
            continue
    if not where:
        raise ValueError("'%s' is not declared in this theme" % name)
    return where


# The CSS colour keywords worth accepting by name. Not all 147: these are the
# ones somebody types on purpose, and an unknown name is refused with a message
# rather than written to a stylesheet where it silently does nothing.
EDITOR_COLOUR_WORDS = set("""
transparent currentcolor inherit initial unset black white red green blue
yellow orange purple pink brown grey gray silver gold navy teal olive maroon
lime aqua cyan magenta fuchsia beige ivory khaki coral salmon crimson firebrick
indigo violet turquoise tomato tan plum orchid linen lavender
darkred darkgreen darkblue darkgrey darkgray darkorange darkviolet darkcyan
lightgrey lightgray lightblue lightgreen lightyellow lightpink
whitesmoke gainsboro dimgrey dimgray slategrey slategray steelblue skyblue
midnightblue royalblue dodgerblue cornflowerblue seagreen forestgreen
""".split())


def looks_like_colour(value):
    """Whether a value will actually paint. Deliberately generous about FORM
    (hex, rgb/hsl, var(), a keyword) and strict about nonsense.

    Without this check, 'not-a-colour' would save with a cheerful
    'Saved --st-accent = not-a-colour', go into the served stylesheet, and
    every session using the theme would quietly lose its accent. A
    stylesheet does not report a bad value; this is the only place that can.
    """
    text = (value or "").strip()
    if not text:
        return False
    if re.match(r'^#[0-9A-Fa-f]{3,8}$', text):
        return True
    if re.match(r'^(rgb|rgba|hsl|hsla|var|color-mix|linear-gradient)\s*\(', text):
        return True
    return text.lower() in EDITOR_COLOUR_WORDS


# How many chips the page draws. Fixed, because Perspective cannot generate
# components from a list -- the page binds a fixed row at fixed indexes, so
# this list is always padded to exactly this length.
EDITOR_SWATCH_COUNT = 16

EDITOR_NOT_A_SWATCH = set(
    "transparent currentcolor inherit initial unset".split())


def swatches(theme, limit=EDITOR_SWATCH_COUNT):
    """The colours this theme already uses, most-used first, padded to a fixed
    length.

    Perspective ships no colour picker: ia.input.form declares a color-picker
    control type with no factory behind it, so a form using one renders as a
    single Component Error (measured on 8.3.8). This and the hex field beside
    it are therefore the whole of colour entry -- and picking from what the
    theme already contains is the better half of it anyway, since those are
    the colours that were chosen to sit together.
    """
    counts = {}
    try:
        values, resolve = _colour_resolver(theme)
        for name in values:
            value = resolve((values.get(name) or "").strip()).strip().lower()
            if value in EDITOR_NOT_A_SWATCH or not looks_like_colour(value):
                continue
            if value.startswith("linear-gradient"):
                continue                 # a chip cannot show one honestly
            counts[value] = counts.get(value, 0) + 1
    except (Exception, Throwable):
        counts = {}                      # padded empties below, never short
    # Most-used first: those are the theme's structural colours, and the tail
    # is one-off accents. Name as the tie-break so the row does not reshuffle
    # between visits.
    found = sorted(counts.keys(), key=lambda c: (-counts[c], c))[:limit]
    # ALWAYS exactly `limit` entries. The page binds a chip to a fixed index,
    # and a short list makes every one of those bindings error -- 16 red boxes
    # where the palette should be. Returning [] on failure did exactly that
    # for the first seconds of a new theme's life.
    return found + [""] * (limit - len(found))


def value_problem(name, old, new):
    """The sentence to refuse a save with, or '' to allow it.

    Judged against what the token ALREADY holds: a theme's values are colours,
    lengths and keywords all in one list, so 'is it a colour' is only a
    question for a token that currently is one.
    """
    text = (new or "").strip()
    if not text:
        return "%s cannot be empty. Type a value, or leave it alone." % name
    if ";" in text or "}" in text:
        return ("%s cannot contain ; or } -- that would break the rest of the "
                "file. Use Advanced if you mean to edit the CSS itself." % name)
    if is_colour(old) and not looks_like_colour(text):
        return ("'%s' is not a colour, so %s would stop working. Use a hex "
                "like #b81d38, a colour name like firebrick, or var(--other) "
                "to point at another value." % (text, name))
    return ""


def set_any_token(theme, name, value):
    """set_token, but it finds the file for you.

    The page cannot pass a filename it never showed the user, and guessing
    variables.css silently edited nothing for every --st-* token: the write
    went to a file that does not declare it, _token_replace raised, and the
    status line said so -- but only after the user had typed a colour and
    pressed Save.
    """
    filename = token_file(theme, name)
    old = ""
    for row in tokens(theme, filename):
        if row["name"] == name:
            old = row["value"]
    problem = value_problem(name, old, value)
    if problem:
        raise ValueError(problem)
    result = set_token(theme, name, value, filename=filename)
    # The value we replaced, so the page can offer to put it back. Nobody
    # remembers the hex they overwrote, and until now nothing else did either.
    if isinstance(result, dict):
        result["was"] = old
        return result
    return {"was": old}

# ---------------------------------------------------------------------------
# IMPORT A THEME SOMEONE ELSE MADE
#
# A theme is CSS that every Perspective session on the gateway loads, so a zip
# from a stranger is checked before anything reaches the themes folder:
#
#   blocked  -- anything that fetches from elsewhere, runs code, hides what it
#               says, or lands outside its own folder. The import stops.
#   warned   -- quality: contrast under WCAG 2.1 AA, no color-scheme, no base
#               theme. Shown in the report; the admin decides.
#
# The upload is STAGED on the gateway and Install re-checks the staged copy, so
# what installs is what was checked, not whatever the page holds by then.
# resource.json and config.json are written here, never taken from the zip.
#
# check_import() touches nothing on the gateway: what it needs to know about
# the gateway arrives as two functions, so the same code runs under CPython in
# tools/test_import.py.
# ---------------------------------------------------------------------------

import hashlib
import shutil
import zipfile

try:
    from StringIO import StringIO as _BytesIO      # Jython 2.7
except ImportError:                                # CPython, tests only
    from io import BytesIO as _BytesIO

IMPORT_MAX_ZIP = 2 * 1024 * 1024
IMPORT_MAX_FILE = 1024 * 1024
IMPORT_MAX_TOTAL = 3 * 1024 * 1024
IMPORT_MAX_ENTRIES = 40
# Carried along in theme zips, read for nothing, never installed.
IMPORT_IGNORED = re.compile(
    r'^(readme|licen[cs]e|notice|changelog)(\.(md|txt))?$|^resource\.json$|'
    r'^config\.json$|^\.ds_store$|\.(png|jpe?g|gif|webp)$', re.I)
IMPORT_MARK = "Imported by Toolbox Theme Manager"

# @import may name another file of this theme, or the base theme it builds on.
_IMP_LOCAL = re.compile(r'^\./([A-Za-z0-9_][A-Za-z0-9_.-]*\.css)$')
_IMP_BASE = re.compile(r'^\.\./([a-z][a-z0-9]*(?:-[a-z0-9]+)*)/index\.css$')
_IMPORT_RE = re.compile(
    r'@import\s+(?:url\(\s*)?(["\']?)([^"\')\s;]*)\1\s*\)?\s*([^;]*);', re.I)
_URL_RE = re.compile(r'url\(\s*(["\']?)(.*?)\1\s*\)', re.I | re.S)
# Inline images and fonts only. Anything else in url() is a fetch from
# somewhere, which a theme loaded by every session must not make.
_URL_OK = re.compile(
    r'^data:(image/(png|jpeg|gif|webp|svg\+xml)|font/(woff2?|ttf|otf)|'
    r'application/(font-woff2?|x-font-woff))[;,]', re.I)
_DANGER = [
    (re.compile(r'expression\s*\(', re.I), "expression() runs script in old browsers"),
    (re.compile(r'javascript\s*:', re.I), "javascript: URL"),
    (re.compile(r'vbscript\s*:', re.I), "vbscript: URL"),
    (re.compile(r'-moz-binding', re.I), "-moz-binding loads code"),
    # Not scroll-behavior or overscroll-behavior, which are ordinary.
    (re.compile(r'(?<![\w-])behaviou?r\s*:', re.I), "behavior: loads code"),
    (re.compile(r'</', re.I), "'</' could close the page's style element "
     "(base64 an inline SVG)"),
    # Takes bare strings as well as url(), so it can fetch without url().
    (re.compile(r'image-set\s*\(', re.I), "image-set() can fetch from elsewhere"),
    (re.compile(r'@namespace|@document|@-moz-document', re.I), "at-rule a theme has no use for"),
    # A hex or letter escape can spell url( or @import so no pattern above
    # sees it. Escaped punctuation cannot, and Perspective style-class
    # selectors need it: .psc-st\/alarms\/list.
    (re.compile(r'\\[0-9A-Za-z]'),
     "backslash escape of a letter or hex code -- can disguise url() or @import"),
]

_IMPORT_TEXT = ["--label", "--label--disabled", "--neutral-100",
                "--error", "--warning", "--success", "--info"]
_IMPORT_SURFACES = ["--containerRoot", "--container", "--containerNested"]
_IMPORT_EDGES = ["--checkbox--unchecked", "--radio--unselected",
                 "--toggleSwitch--unselected"]


def _imp_colour(value):
    """(r, g, b, a) for hex or rgb()/rgba(), else None."""
    value = (value or "").strip()
    m = re.match(r'^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$', value)
    if m:
        h = m.group(1)
        if len(h) == 3:
            h = "".join(c * 2 for c in h)
        return (int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16), 1.0)
    m = re.match(r'^rgba?\(([^)]+)\)$', value)
    if m:
        parts = [p.strip() for p in m.group(1).replace("/", ",").split(",")]
        try:
            rgb = tuple(float(p) for p in parts[:3])
            a = float(parts[3]) if len(parts) > 3 else 1.0
        except ValueError:
            return None
        return rgb + (a,)
    return None


def _imp_over(fg, bg):
    """fg composited over an opaque bg."""
    a = fg[3]
    return tuple(fg[i] * a + bg[i] * (1 - a) for i in range(3)) + (1.0,)


def _imp_ratio(a, b):
    def lum(c):
        out = []
        for v in c[:3]:
            v = v / 255.0
            out.append(v / 12.92 if v <= 0.03928 else ((v + 0.055) / 1.055) ** 2.4)
        return 0.2126 * out[0] + 0.7152 * out[1] + 0.0722 * out[2]
    la, lb = lum(a), lum(b)
    return (max(la, lb) + 0.05) / (min(la, lb) + 0.05)


def _imp_resolve(values, name):
    value, hops = values.get(name), 0
    while value and hops < 8:
        m = re.match(r'^var\(\s*(--[A-Za-z0-9_-]+)\s*(?:,[^)]*)?\)$', value.strip())
        if not m:
            break
        value, hops = values.get(m.group(1)), hops + 1
    return value


def import_contrast(values):
    """WCAG 2.1 AA misses for the stock variables every Perspective component
    reads: text 4.5:1 and control edges 3:1 on the three surfaces."""
    page = _imp_colour(_imp_resolve(values, "--containerRoot"))
    white = (255.0, 255.0, 255.0, 1.0)
    page = _imp_over(page, white) if page else white
    misses, unchecked = [], []
    for fgs, floor in ((_IMPORT_TEXT, 4.5), (_IMPORT_EDGES, 3.0)):
        for fg in fgs:
            for bg in _IMPORT_SURFACES:
                f = _imp_colour(_imp_resolve(values, fg))
                b = _imp_colour(_imp_resolve(values, bg))
                if not f or not b:
                    if values.get(fg) and values.get(bg):
                        unchecked.append("%s on %s" % (fg, bg))
                    continue
                b = _imp_over(b, page)
                ratio = _imp_ratio(_imp_over(f, b), b)
                if ratio < floor:
                    misses.append({"fg": fg, "bg": bg,
                                   "ratio": round(ratio, 2), "floor": floor})
    return misses, unchecked


def _imp_vars(css):
    """Custom properties a file declares, last wins. Unlike _vars_of this
    does not need one per line: a stranger's CSS may be minified."""
    found = {}
    for m in re.finditer(r'(--[A-Za-z0-9_-]+)\s*:\s*([^;{}]+)', css):
        found[m.group(1)] = m.group(2).strip()
    return found


def _imp_strip_comments(css):
    return re.sub(r'/\*.*?\*/', '', css, flags=re.S)


def _imp_check_css(filename, css, files, kind_of, blocks, notes):
    """Block-level checks on one stylesheet. Returns the base theme it
    @imports, if any."""
    base = None
    body = _imp_strip_comments(css)
    if "/*" in body:
        blocks.append("%s: a comment is never closed" % filename)
    for pattern, why in _DANGER:
        if pattern.search(body):
            blocks.append("%s: %s" % (filename, why))
    for m in _IMPORT_RE.finditer(body):
        target, media = m.group(2), m.group(3).strip()
        local, other = _IMP_LOCAL.match(target), _IMP_BASE.match(target)
        if media:
            blocks.append("%s: @import with a media or layer condition (%s)"
                          % (filename, media))
        elif local:
            if local.group(1) not in files:
                blocks.append("%s: @import of %s, which is not in the zip"
                              % (filename, local.group(1)))
        elif other and filename == "index.css":
            kind = kind_of(other.group(1))
            if kind == "missing":
                blocks.append("index.css builds on '%s', which this gateway "
                              "does not have" % other.group(1))
            elif kind != "stock":
                notes.append("Builds on '%s' rather than one of Ignition's "
                             "own themes; removing that theme would break "
                             "this one." % other.group(1))
            if base and base != other.group(1):
                blocks.append("index.css builds on two themes")
            base = other.group(1)
        else:
            blocks.append("%s: @import of '%s' -- only ./file.css or "
                          "../<theme>/index.css (from index.css) is allowed"
                          % (filename, target))
    # Every @import must be one the pattern above understood.
    if len(re.findall(r'@import', body, re.I)) != len(_IMPORT_RE.findall(body)):
        blocks.append("%s: an @import this check cannot read" % filename)
    for m in _URL_RE.finditer(body):
        if not _URL_OK.match(m.group(2).strip()):
            shown = m.group(2).strip()
            blocks.append("%s: url(%s) -- only inline data: images and fonts "
                          "are allowed; a theme must not fetch anything"
                          % (filename, shown[:60] + ("..." if len(shown) > 60 else "")))
    if re.search(r'\bcontent\s*:\s*["\'][^"\']*[A-Za-z]{3}', body):
        notes.append("%s adds text to the page with content: -- read it "
                     "before installing." % filename)
    return base


def check_import(data, zip_name, name=None, kind_of=None, base_vars=None):
    """Check a theme zip. Returns the report; installs nothing.

    data      the zip as a byte string
    name      the theme id to install as; defaults to the zip's folder or name
    kind_of   id -> 'packaged' | 'stock' | 'user' | 'missing'
    base_vars id -> {variable: value} the gateway serves for that theme
    """
    kind_of = kind_of or theme_kind
    report = {"ok": False, "id": "", "dark": None, "base": None, "files": {},
              "blocks": [], "warnings": [], "ignored": [],
              "contrast": [], "sha256": hashlib.sha256(data).hexdigest(),
              "zip": zip_name}
    blocks, notes = report["blocks"], report["warnings"]
    if len(data) > IMPORT_MAX_ZIP:
        blocks.append("The zip is %d KB; the limit is %d KB"
                      % ((len(data) + 1023) // 1024, IMPORT_MAX_ZIP // 1024))
        return report
    try:
        zf = zipfile.ZipFile(_BytesIO(data))
        infos = zf.infolist()
    except Exception:
        blocks.append("Not a zip file this can read")
        return report
    if len(infos) > IMPORT_MAX_ENTRIES:
        blocks.append("%d entries in the zip; a theme has a handful"
                      % len(infos))
        return report

    # Either the files at the top, or all of them in one folder.
    names = [i.filename for i in infos if not i.filename.endswith("/")]
    tops = set(n.split("/")[0] for n in names if "/" in n)
    folder = tops.pop() if len(tops) == 1 and all("/" in n for n in names) else ""
    total = 0
    for info in infos:
        path = info.filename
        if path.endswith("/"):
            continue
        rel = path[len(folder) + 1:] if folder else path
        mode = (info.external_attr >> 16) & 0o170000
        if ("\\" in path or path.startswith("/") or ".." in path.split("/")
                or ":" in path):
            blocks.append("%s: path leaves the theme folder" % path)
            continue
        if mode == 0o120000:
            blocks.append("%s: symbolic link" % path)
            continue
        if info.flag_bits & 0x1:
            blocks.append("%s: encrypted" % path)
            continue
        if "/" in rel:
            blocks.append("%s: sub-folders are not part of a theme" % path)
            continue
        if IMPORT_IGNORED.search(rel):
            report["ignored"].append(rel)
            continue
        if not re.match(r'^[A-Za-z0-9_][A-Za-z0-9_.-]*\.css$', rel):
            blocks.append("%s: only .css files are installed; scripts, "
                          "markup and other files are refused" % rel)
            continue
        if info.file_size > IMPORT_MAX_FILE:
            blocks.append("%s is %d KB; the limit is %d KB"
                          % (rel, (info.file_size + 1023) // 1024, IMPORT_MAX_FILE // 1024))
            continue
        # Read one byte past the limit: the header's size can lie.
        raw = zf.open(info).read(IMPORT_MAX_FILE + 1)
        total += len(raw)
        if len(raw) > IMPORT_MAX_FILE or total > IMPORT_MAX_TOTAL:
            blocks.append("%s: larger than its header says, or the theme is "
                          "over %d KB in all" % (rel, IMPORT_MAX_TOTAL // 1024))
            continue
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            blocks.append("%s is not UTF-8 text" % rel)
            continue
        if "\x00" in text:
            blocks.append("%s contains NUL characters" % rel)
            continue
        report["files"][rel] = text

    files = report["files"]
    if "index.css" not in files:
        blocks.append("No index.css -- the gateway loads a theme through it")

    stem = re.sub(r'\.zip$', '', (zip_name or "").split("/")[-1], flags=re.I)
    theme_id = (name or folder or stem or "").strip().lower()
    theme_id = re.sub(r'[\s_]+', '-', theme_id)
    report["id"] = theme_id
    if not EDITOR_ID_RE.match(theme_id):
        blocks.append("'%s' is not a usable theme id -- lower-case letters "
                      "and digits, words joined by single hyphens; give it "
                      "a name" % theme_id)
    else:
        kind = kind_of(theme_id)
        if kind != "missing":
            blocks.append("A theme called '%s' is already on this gateway "
                          "(%s) -- give the import another name"
                          % (theme_id, {"packaged": "one of ours",
                                        "stock": "one of Ignition's",
                                        "user": "made or imported here"}
                             .get(kind, kind)))

    base = None
    for filename in sorted(files):
        found = _imp_check_css(filename, files[filename], files, kind_of,
                               blocks, notes)
        base = base or found
    report["base"] = base

    own = {}
    for filename in sorted(files):
        if filename != "index.css":
            own.update(_imp_vars(_imp_strip_comments(files[filename])))
    own.update(_imp_vars(_imp_strip_comments(files.get("index.css", ""))))
    scheme = re.search(r'color-scheme\s*:\s*([a-z ]+)',
                       _imp_strip_comments("".join(files.values())))
    if base:
        report["dark"] = "dark" in base
    if scheme:
        report["dark"] = "dark" in scheme.group(1) and "light" not in scheme.group(1)
    else:
        notes.append("No color-scheme declaration. Without one Chrome's auto "
                      "dark mode can repaint charts white.")
    if not base:
        notes.append("index.css does not build on another theme, so every "
                     "variable it leaves out has no value and those parts "
                     "of Perspective render unstyled.")

    values = {}
    if base and base_vars:
        try:
            values.update(base_vars(base))
        except Exception:
            notes.append("Could not read '%s' to check contrast against "
                         "what it inherits." % base)
    values.update(own)
    misses, unchecked = import_contrast(values)
    report["contrast"] = misses
    if misses:
        notes.append("%d text or control-edge pairs are under WCAG 2.1 AA "
                     "contrast (listed below)." % len(misses))
    if unchecked:
        notes.append("%d pairs could not be checked (gradients or keywords)."
                     % len(unchecked))
    report["values"] = values
    report["ok"] = not blocks
    return report


# ---- gateway side: stage, report, install ----------------------------------

def _import_dir():
    path = os.path.join(_data_dir(), "theme-manager", "imports")
    if not os.path.isdir(path):
        os.makedirs(path)
    return path


def _import_base_vars(base):
    return _vars_of(theme_css(base))


def import_bytes(file_bytes):
    """A Perspective upload's Java byte[] as a byte string. Not
    StringUtil.fromBytes: in Ignition's Jython that returns unicode, and the
    zip reader then sees mangled bytes."""
    return file_bytes.tostring()


def _staged(token):
    if not re.match(r'^[0-9a-f]{24}$', token or ""):
        raise ValueError("No staged import")
    return os.path.join(_import_dir(), token + ".zip")


def _import_report(data, zip_name, name, token):
    """The report for the page: findings, file names and a preview, not the
    file text or a few hundred variables."""
    report = check_import(data, zip_name, name, theme_kind, _import_base_vars)
    report["token"] = token
    report["preview"] = import_preview_uri(report) if report["ok"] else ""
    report["files"] = sorted(report["files"])
    report.pop("values", None)
    return report


def stage_import(data, zip_name, name=None):
    """Keep an upload on the gateway and check it. Kept even when refused, so
    a new name can be tried without uploading again. Staged copies older than
    a day are cleared out here."""
    import time
    root = _import_dir()
    for old in os.listdir(root):
        path = os.path.join(root, old)
        if time.time() - os.path.getmtime(path) > 86400:
            os.remove(path)
    if len(data) > IMPORT_MAX_ZIP:
        return check_import(data, zip_name, name, theme_kind, _import_base_vars)
    token = hashlib.sha256(data).hexdigest()[:24]
    _write_bytes(_staged(token), data)
    return _import_report(data, zip_name, name, token)


def recheck_import(token, zip_name, name=None):
    return _import_report(_read_bytes(_staged(token)), zip_name, name, token)


def _write_bytes(path, data):
    fh = open(path, "wb")
    try:
        fh.write(data)
    finally:
        fh.close()


def _read_bytes(path):
    fh = open(path, "rb")
    try:
        return fh.read()
    finally:
        fh.close()


def import_preview_uri(report, width=340, height=102):
    """The same mini screen as the status table, from the checked values."""
    return live_preview_uri(None, width, height, values=report.get("values") or {})


def install_import(token, zip_name, name=None):
    """Re-check the staged zip and install it. Refuses unless it passes."""
    path = _staged(token)
    data = _read_bytes(path)
    report = check_import(data, zip_name, name, theme_kind, _import_base_vars)
    if not report["ok"] or report["sha256"][:24] != token:
        raise ValueError("The staged theme no longer passes: %s"
                         % ("; ".join(report["blocks"]) or "changed on disk"))
    theme_dir = os.path.join(_themes_root(), report["id"])
    # Staged then renamed into place: a scan that reads a half-written theme
    # skips it silently and does not come back to it.
    stage = theme_dir + ".importing"
    if os.path.isdir(stage):
        shutil.rmtree(stage)
    os.makedirs(stage)
    files = dict(report["files"])
    files["config.json"] = json.dumps(
        {"entrypoint": "index.css", "isPrivate": False}, indent=2) + "\n"
    for filename, text in files.items():
        _write(os.path.join(stage, filename), text)
    import datetime
    doc = {"scope": "G", "version": 1, "restricted": False,
           "overridable": True, "attributes": {},
           "description": "%s from %s (sha256 %s) on %s" % (
               IMPORT_MARK, zip_name, report["sha256"][:16],
               datetime.date.today().isoformat()),
           "files": sorted(files)}
    _write(os.path.join(stage, "resource.json"), json.dumps(doc, indent=2))
    os.rename(stage, theme_dir)
    os.remove(path)
    _rescan()
    return report["id"]


def imported_themes():
    """Ids of themes this page imported, read off their resource.json."""
    out = []
    for name in user_themes():
        try:
            doc = json.loads(_read(os.path.join(_themes_root(), name,
                                                "resource.json")))
        except (Exception, Throwable):
            continue
        if (doc.get("description") or "").startswith(IMPORT_MARK):
            out.append(name)
    return out


def remove_imported(names):
    """Delete the named themes if, and only if, this page imported them."""
    mine = set(imported_themes())
    done = [n for n in (names or []) if n in mine]
    for name in done:
        delete_theme(name)
    return done


# What fits the popup at 1366x640 without clipping.
IMPORT_SHOWN = 8


def import_view(report, error=None):
    """What the Import popup shows, as plain strings it can bind to."""
    report = report or {}
    if error:
        return {"ok": False, "token": "", "id": "", "preview": "",
                "verdict": "Not checked: %s" % error, "details": "",
                "findings": ""}
    blocks = report.get("blocks") or []
    if report.get("ok"):
        verdict = "Passes the checks. Installs as '%s'." % report["id"]
    else:
        verdict = ("Refused: %d problem%s below. Nothing has been written to "
                   "the themes folder." % (len(blocks),
                                           "" if len(blocks) == 1 else "s"))
    mode = {True: "dark", False: "light"}.get(report.get("dark"), "unknown")
    details = "%s  |  builds on %s  |  %s  |  files %s" % (
        report.get("zip") or "", report.get("base") or "nothing", mode,
        ", ".join(report.get("files") or []) or "nothing")
    if report.get("ignored"):
        details += "  |  left out: %s" % ", ".join(report["ignored"])
    lines = ["Refused: " + b for b in blocks]
    lines += ["Warning: " + w for w in report.get("warnings") or []]
    lines += ["  %s on %s is %.2f:1, needs %.1f:1" % (
        c["fg"], c["bg"], c["ratio"], c["floor"])
        for c in report.get("contrast") or []]
    if len(lines) > IMPORT_SHOWN:
        lines = lines[:IMPORT_SHOWN - 1] + [
            "... and %d more" % (len(lines) - IMPORT_SHOWN + 1)]
    return {"ok": bool(report.get("ok")), "token": report.get("token") or "",
            "id": report.get("id") or "", "preview": report.get("preview") or "",
            "verdict": verdict, "details": details,
            "findings": "\n".join(lines) or "No warnings."}
